\label{thm.Rp}
Let $A$ and $\Omega$ be the same as in Theorem \ref{thm.Dp}.
     Let $u_\varepsilon\in H^1(\Omega)$ be a weak solution of $\mathcal{L}_\varepsilon (u_\varepsilon)=0$ in $\Omega$
     with the Dirichlet condition $u_\varepsilon=f\in H^1(\partial\Omega)$
     on $\partial\Omega$. Then there exists $\delta>0$, depending only on $d$,  $\Lambda$ and $\Omega$, such that for $1<p<2+\delta$,
    \begin{equation}\label{est.Rp}
        \| \widetilde{N}_\varepsilon( \nabla u_\varepsilon) \|_{L^p(\partial \Omega)} 
        \le C\| f \|_{W^{1,p}(\partial \Omega)},
    \end{equation}
    where $C$ depends on $d$, $p$,  $\Lambda$ and $\Omega$.
    Moreover, if $\Omega$ is a bounded $C^1$ domain,
    the estimate \eqref{est.Rp} holds for $1< p< \infty$.

For $Q\in \partial \Omega$, the nontangential region at $Q$ is defined by
    \begin{equation}
        \Gamma(Q) = \{ X\in \Omega: |X-Q| < \beta \mathrm{dist}(X,\partial \Omega)  \},
    \end{equation}
    where $\beta>1$ is a large fixed constant depending on the Lipschitz character of $\Omega$.

define the ($\varepsilon$-scale) average operator $M_\varepsilon$ in $\Omega$ by
    \begin{equation}
        M_\varepsilon(u)(X) = \bigg( \fint_{B_\varepsilon(X) \cap \Omega} |u|^2 \bigg)^{1/2}.

we define the boundary average operator by
    \begin{equation}
        M_\varepsilon^{\partial}(f)(Q) = \bigg( \fint_{\Delta_\varepsilon(Q)} |f|^2 d\sigma \bigg)^{1/2}.

\label{prop.hmBasics}
    Let $\Omega$ be a bounded Lipschitz domain and $Q\in \partial \Omega$.
    \begin{enumerate}[label=(\roman*)]
        \item \label{item.doubling}
        $\omega^X_\varepsilon$ is doubling, i.e., for $X\in \Omega \setminus B_{4r}(Q)$,
        \begin{equation}
            \omega^X_\varepsilon(\Delta_{2r}(Q)) \lesssim \omega^X_\varepsilon(\Delta_{r}(Q)).
        \end{equation}
        \item \label{item.w=1} It holds
        \begin{equation}
            \omega_\varepsilon^{A_r(Q)}(\Delta_{r}(Q)) \simeq 1.
        \end{equation}

        \item  \label{item.w=G}  
        For $X\in \Omega \setminus B_{2r}(Q)$, 
    \begin{equation}\label{est.w=G}
        \omega_\varepsilon^X(\Delta_r(Q)) \simeq r^{d-2} G_\varepsilon(X, A_r(Q)).
    \end{equation}
        \item \label{item.G-L2}
        For $X\in \Omega \setminus B_{2r}(Q)$,
    \begin{equation}
        G_\varepsilon(X, A_r(Q)) \simeq \bigg( \fint_{\Omega \cap B_r(Q)} |G_\varepsilon(X,Y)|^2 dY\bigg)^{1/2}.
    \end{equation}

    \item \label{item.G.Holder}
    There exists $\alpha \in (0,1)$ such that for $X,Y\in \Omega$ and $\delta(X) < \frac12 |X-Y|$, 
    \begin{equation}
        G_\varepsilon(X,Y) \lesssim \frac{\delta(X)^\alpha}{|X-Y|^{d-2+\alpha}}.
    \end{equation}
    \end{enumerate}

By a translation and a rotation, we can assume
\begin{equation}\label{eq.graphdomain}
    B(P_i, 10r_0) \cap \Omega = B(0,10r_0) \cap \left\{ X = (x',x_d): x_d > \phi(x') \right\},
\end{equation}
where $\phi:\mathbb{R}^{d-1} \to \mathbb{R}$ is a Lipschitz function, representing the local graph of $\partial \Omega$.

Given $Q = (x',\phi(x')) \in \partial \Omega$, let 
\begin{equation}\label{I-r}
I_r(Q) = \left\{ P = (y',\phi(y')): |y'-x'|<r \right\}
\end{equation}
and 
\begin{equation}\label{T-r}
T_r(Q) = \left\{ Y = (y',y_d): |y'-x'|<r, \phi(y') < y_d < \phi(x') + M r \right\},
\end{equation}
where $M=100d(1+ \| \nabla \phi \|_\infty).$
These are analogs of $\Delta_r(Q)$ and $D_r(Q)$.

Without loss of generality, we assume $\ell = 1$, which yields
\begin{equation}\label{eq.periodicInxd}
