\label{prop.LSRellich}
    Let $\varepsilon \le r$. Let $u_\varepsilon$ be a weak solution of $\mathcal{L}_\varepsilon(u_\varepsilon) = 0$ in $D_{2r}(Q) = \Omega \cap B_{2r}(Q)$ for some $Q \in \partial \Omega$, and $u_\varepsilon = 0$ on $\Delta_{2r}(Q)$. Then for any $t\in [\varepsilon,r]$, 
    \begin{equation}
        \frac{1}{t} \int_{D_r(Q) \cap \Omega_t} |\nabla u_\varepsilon|^2 \lesssim \frac{1}{r} \int_{D_{2r}(Q)} |\nabla u_\varepsilon|^2.
    \end{equation}

\label{lem.doubling}
For any $0<r<r_0, \Delta_r = \Delta_r(P), X \in \Omega $ and $|X - P| > 5\max\{ r,\varepsilon \}$, we have
\begin{equation}\label{est.doubling}
    \int_{\Delta_{2r}} \overline{\omega}^X_\varepsilon(Q) d\sigma(Q) \lesssim \int_{\Delta_{r}} \overline{\omega}^X_\varepsilon(Q) d\sigma(Q).
\end{equation}

First, consider $r<10\varepsilon$. In this case, by the doubling property of $\omega_\varepsilon^X$, for any $Q, Q' \in \Delta_{2\varepsilon}(P)$, we have $\omega_\varepsilon^X(\Delta_\varepsilon(Q)) \simeq  \omega_\varepsilon^X(\Delta_\varepsilon(Q'))$. 
Here we have used the assumption $|X-P|>5\varepsilon$.
This implies that $\overline{\omega}^X_\varepsilon(Q) \simeq \overline{\omega}^X_\varepsilon(Q') $ for any $Q, Q^\prime\in \Delta_{2r} \subset \Delta_{2\varepsilon}(P)$. Thus, \eqref{est.doubling} follows.

Now consider the case $r\ge 10\varepsilon$. By Fubini's Theorem, we have
\begin{equation}\label{est.doubling<}
    \begin{aligned}
        \int_{\Delta_{2r}} \overline{\omega}^X_\varepsilon(Q) d\sigma(Q) & = \int_{\Delta_{2r}} \int_{\Delta_{2r+\varepsilon}} \mathbbm{1}_{\{|Q'-Q|<\varepsilon\}} |\Delta_\varepsilon(Q')|^{-1} d\omega_\varepsilon^X(Q') d\sigma(Q) \\
        & \lesssim \int_{\Delta_{2r+\varepsilon}} \int_{\Delta_{2r}} \mathbbm{1}_{\{|Q'-Q|<\varepsilon\}} d\sigma(Q) \varepsilon^{1-d} d\omega_\varepsilon^X(Q') \\
        & \lesssim \int_{\Delta_{2r+\varepsilon}} d\omega_\varepsilon^X(Q') \\
        & \lesssim \omega_\varepsilon^X(\Delta_{2r+\varepsilon}) \lesssim \omega_\varepsilon^X(\Delta_{r-\varepsilon}),
    \end{aligned}
\end{equation}
where in the last line we have used the fact $2r+\varepsilon \le 3(r-\varepsilon)$ for $r\ge 10\varepsilon$ and the doubling property of $\omega_\varepsilon^X$ in Proposition \ref{prop.hmBasics} \ref{item.doubling}.

On the other hand, using Fubini's Theorem again, we have
\begin{equation}
\begin{aligned}
    \int_{\Delta_{r}} \overline{\omega}^X_\varepsilon(Q) d\sigma(Q) & = \int_{\Delta_{r}} \int_{\Delta_{r+\varepsilon}} \mathbbm{1}_{\{|Q'-Q|<\varepsilon\}} |\Delta_\varepsilon(Q')|^{-1} d\omega_\varepsilon^X(Q') d\sigma(Q) \\
    & \gtrsim \int_{\Delta_{r+\varepsilon}} \int_{\Delta_{r}} \mathbbm{1}_{\{|Q'-Q|<\varepsilon\}} d\sigma(Q) \varepsilon^{1-d} d\omega_\varepsilon^X(Q').
\end{aligned}
\end{equation}
Observe that for $Q'\in \Delta_{r-\varepsilon}$,
\begin{equation}
    \int_{\Delta_{r}} \mathbbm{1}_{\{|Q'-Q|<\varepsilon\}} d\sigma(Q) = \sigma(\Delta_\varepsilon(Q')) \simeq \varepsilon^{d-1}.
\end{equation}
It follows that
\begin{equation}\label{est.doubling>}
    \int_{\Delta_{r}} \overline{\omega}^X_\varepsilon(Q) d\sigma(Q) \gtrsim \int_{\Delta_{r-\varepsilon}} d\omega_\varepsilon^X(Q') = \omega_\varepsilon^X(\Delta_{r-\varepsilon}).
\end{equation}
Combining \eqref{est.doubling<} and \eqref{est.doubling>}, we get \eqref{est.doubling}.

\begin{equation}\label{est.doubling<}
        \begin{aligned}
            \int_{\Delta_{2r}} \overline{\omega}^X_\varepsilon(Q) d\sigma(Q) & = \int_{\Delta_{2r}} \int_{\Delta_{2r+\varepsilon}} \mathbbm{1}_{\{|Q'-Q|<\varepsilon\}} |\Delta_\varepsilon(Q')|^{-1} d\omega_\varepsilon^X(Q') d\sigma(Q) \\
            & \lesssim \int_{\Delta_{2r+\varepsilon}} \int_{\Delta_{2r}} \mathbbm{1}_{\{|Q'-Q|<\varepsilon\}} d\sigma(Q) \varepsilon^{1-d} d\omega_\varepsilon^X(Q') \\
            & \lesssim \int_{\Delta_{2r+\varepsilon}} d\omega_\varepsilon^X(Q') \\
            & \lesssim \omega_\varepsilon^X(\Delta_{2r+\varepsilon}) \lesssim \omega_\varepsilon^X(\Delta_{r-\varepsilon}),
        \end{aligned}
    \end{equation}

\label{thm.B2}
    It holds $\overline{\omega}_\varepsilon^X \in B_2(d\sigma)$ uniformly in $\varepsilon$, in the sense that, any $r > 0, P\in \partial \Omega, X \in \Omega$ and $|X-P| > 5\max \{r, \varepsilon \}$,
    \begin{equation}\label{est.B2}
        \bigg( \fint_{\Delta_r(P)} \overline{\omega}_\varepsilon^X(Q)^2 d\sigma(Q) \bigg)^{1/2} \lesssim \fint_{\Delta_{r}(P)} \overline{\omega}_\varepsilon^X(Q) d\sigma(Q).
    \end{equation}

The case $r<10\varepsilon$ follows by the same reasoning as Lemma \ref{lem.doubling}. It suffices to assume $r>10\varepsilon$. Let $\Delta_r = \Delta_r(P)$ and $B_r = B_r(P)$.

By Proposition \ref{prop.hmBasics} \ref{item.w=G}, \ref{item.G-L2}  and \eqref{def.LSomega}, for each $Q\in \Delta_r$,
\begin{equation}
    \overline{\omega}_\varepsilon^X(Q) \simeq \varepsilon^{-1} G(X, A_\varepsilon(Q)) \lesssim \bigg( \fint_{B_{2\varepsilon}(Q) \cap \Omega} |\nabla_Y G_\varepsilon(X, Y)|^2 dY \bigg)^{1/2},
\end{equation}
where we also used the Poincar\'{e} inequality. Thus, by Fubini's Theorem, Proposition \ref{prop.LSRellich}, Caccioppoli's inequality and Proposition \ref{prop.hmBasics} \ref{item.G-L2}, \ref{item.w=G}, in order, we have
\begin{equation}
\begin{aligned}
    \int_{\Delta_r} \overline{\omega}_\varepsilon^X(Q)^2 d\sigma(Q) & \lesssim \varepsilon^{-d} \int_{\Delta_r} \int_{B_{2\varepsilon(Q)} \cap \Omega} |\nabla_Y G_\varepsilon(X,Y)|^2 dY d\sigma \\
    & \lesssim \varepsilon^{-d} \int_{\Omega_{2\varepsilon} \cap B_{1.5r}} |\nabla G(X,Y)|^2 \int_{\Delta_r} \mathbbm{1}_{|Y-Q| < 2\varepsilon} d\sigma dY\\
    & \lesssim \varepsilon^{-1} \int_{\Omega_{2\varepsilon} \cap B_{1.5r}} |\nabla G_\varepsilon(X,Y)|^2 dY \\
    & \lesssim r^{-1} \int_{D_{3r}} |\nabla G_\varepsilon(X,Y)|^2 dY \\
    & \lesssim r^{-3} \int_{D_{4r}} |G_\varepsilon(X, Y)|^2 dY \\
    & \lesssim r^{d-3} |G_\varepsilon(X, A_r(P))|^2 \\
    & \simeq r^{1-d} \omega_\varepsilon^X(\Delta_r)^2.
\end{aligned}
\end{equation}
Dividing both sides by $r^{d-1}$ and taking square root, we obtain
\begin{equation}
    \bigg( \fint_{\Delta_r} \overline{\omega}_\varepsilon^X(Q)^2 d\sigma(Q) \bigg)^{1/2} \lesssim \frac{\omega_\varepsilon^X(\Delta_r)}{\sigma(\Delta_r)} \lesssim  \frac{\omega_\varepsilon^X(\Delta_{r/2})}{\sigma(\Delta_r)} \lesssim \fint_{\Delta_{r}} \overline{\omega}_\varepsilon^X(Q) d\sigma(Q),
\end{equation}
where we also used the doubling property of $\omega^X_\varepsilon$ in Proposition \ref{prop.hmBasics} \ref{item.doubling}, and Fubini's Theorem in the last inequality.

\begin{equation}
    \begin{aligned}
        \int_{\Delta_r} \overline{\omega}_\varepsilon^X(Q)^2 d\sigma(Q) & \lesssim \varepsilon^{-d} \int_{\Delta_r} \int_{B_{2\varepsilon(Q)} \cap \Omega} |\nabla_Y G_\varepsilon(X,Y)|^2 dY d\sigma \\
        & \lesssim \varepsilon^{-d} \int_{\Omega_{2\varepsilon} \cap B_{1.5r}} |\nabla G(X,Y)|^2 \int_{\Delta_r} \mathbbm{1}_{|Y-Q| < 2\varepsilon} d\sigma dY\\
        & \lesssim \varepsilon^{-1} \int_{\Omega_{2\varepsilon} \cap B_{1.5r}} |\nabla G_\varepsilon(X,Y)|^2 dY \\
        & \lesssim r^{-1} \int_{D_{3r}} |\nabla G_\varepsilon(X,Y)|^2 dY \\
        & \lesssim r^{-3} \int_{D_{4r}} |G_\varepsilon(X, Y)|^2 dY \\
        & \lesssim r^{d-3} |G_\varepsilon(X, A_r(P))|^2 \\
