    \end{aligned}
    \end{equation}

\label{coro.2+delta}
    There exists $\delta>0$, depending on $d$, $\Lambda$ and $\Omega$, such that $\overline{\omega}_\varepsilon^X \in B_{2+\delta}(d\sigma)$ in the sense that for any $r>0, P\in \partial \Omega, X\in \Omega$ and $|X - P| > 5\max \{r, \varepsilon\}$,
    \begin{equation}
        \bigg( \fint_{\Delta_r(P)} \overline{\omega}_\varepsilon^X(Q)^{2+\delta} d\sigma(Q) \bigg)^{1/(2+\delta)} \lesssim \fint_{\Delta_{r}(P)} \overline{\omega}_\varepsilon^X(Q) d\sigma(Q).
    \end{equation}

\label{thm.Neve<f}
    Let $f\in C(\partial \Omega)$ and
    \begin{equation}\label{def.ve}
        v_\varepsilon(X) = \int_{\partial \Omega} f(Q) \overline{\omega}^X_\varepsilon(Q) d\sigma(Q).
    \end{equation}
    Then $v_\varepsilon$ is a solution of
    \begin{equation}\label{eq.ve=barf}
    \left\{
    \begin{aligned}
        & \mathcal{L}_\varepsilon(v_\varepsilon) = 0 \quad \text{in } \Omega, \\
        & v_\varepsilon(Q) = \bar{f}(Q) := \int_{\Delta_\varepsilon(Q)} |\Delta_\varepsilon|^{-1} f d\sigma \quad \text{on } \partial \Omega,
    \end{aligned}
    \right.
\end{equation}
where $|\Delta_\varepsilon| = |\Delta_\varepsilon(P)| \simeq \varepsilon^{d-1}$.
    Moreover, for any $p\in (2-\delta, \infty)$,
    \begin{equation}\label{est.Neve}
        \| N_\varepsilon(v_\varepsilon) \|_{L^p(\partial \Omega)} \lesssim \| f \|_{L^p(\partial \Omega)}.
    \end{equation}

    By Fubini's Theorem,
    \begin{equation}
    \begin{aligned}
        v_\varepsilon(X) & = \int_{\partial \Omega} \int_{\partial \Omega} |\Delta_\varepsilon(Q)|^{-1} f(Q) 1_{\Delta_\varepsilon(Q)}(P) d\omega^X_\varepsilon(P) d\sigma(Q) \\ & = \int_{\partial \Omega} \int_{\partial \Omega} |\Delta_\varepsilon(Q)|^{-1} f(Q) 1_{\Delta_\varepsilon(P)}(Q) d\sigma(Q) d\omega_\varepsilon^X(P) \\
        & = \int_{\partial \Omega} \int_{\Delta_\varepsilon(P)} |\Delta_\varepsilon(Q)|^{-1} f(Q) d\sigma(Q) d\omega_\varepsilon^X(P)\\
        & = \int_{\partial \Omega} \bar{f} d\omega_\varepsilon^X.
    \end{aligned}
    \end{equation}
    This proves \eqref{eq.ve=barf}.

    Next, we prove \eqref{est.Neve}. Let $X\in \Gamma(Q)$ and $\mathrm{dist}(X,\partial \Omega) > 10\varepsilon$. Let $r_0 = c|X - Q|$ and $r_j = 2^j r_0$. Let $R_0 = \Delta_{r_0}(Q)$, $R_j = \Delta_{r_j}(Q) \setminus \Delta_{r_{j-1}}(Q)$ for $j = 1,2, \cdots, L$, where $L$ is the minimal integer such that $2^L r_0 \ge c\mathrm{diam}(\Omega)$,
    and $R_{L+1} = \partial\Omega \setminus \Delta_{r_L}$. Then
    \begin{equation}
        \partial \Omega = \bigcup_{j = 0}^{L+1} R_j.
    \end{equation}
    Observe that for every $j = 0,1,\cdots, L+1$, we have $\mathrm{dist}(X, R_j) \simeq 2^j r_0$. Thus, Corollary \ref{coro.2+delta} and a covering argument yields
    \begin{equation}
        \bigg( \fint_{R_j} \overline{\omega}_\varepsilon^X(Q)^{2+\delta} d\sigma(Q) \bigg)^{1/(2+\delta)} \lesssim \fint_{R_j} \overline{\omega}_\varepsilon^X(Q) d\sigma(Q).
    \end{equation}

    Now, we bound \eqref{def.ve} by
    \begin{equation}\label{est.BdryDecomp}
    \begin{aligned}
    |v_\varepsilon(X)| & \lesssim \sum_{j = 0}^{L+1} \int_{R_j} |f(P')| \overline{\omega}_\varepsilon^X(P') d\sigma(P')\\
    & \le \sum_{j = 0}^{L+1} \bigg(\int_{R_j} |f(P')|^{p'_0} d\sigma(P') \bigg)^{1/p'_0} \bigg( \int_{R_j} \overline{\omega}_\varepsilon^X(P')^{p_0} d\sigma(P') \bigg)^{1/p_0} \\
    & \lesssim \sum_{j = 0}^{L+1} \bigg(\int_{R_j} |f(P')|^{p'_0} d\sigma(P') \bigg)^{1/p'_0} \int_{R_j} \overline{\omega}_\varepsilon^X(P') d\sigma(P') |R_j|^{-1/p^\prime_0}, 

    \end{aligned}
\end{equation}
where $p_0=2+\delta$.
By the definition of $\overline{\omega}_\varepsilon^X$ and Proposition \ref{prop.hmBasics} \ref{item.w=G} \ref{item.G.Holder},
\begin{equation}
    \int_{R_j} \overline{\omega}_\varepsilon^X(P') d\sigma(P') \lesssim \int_{R_j} d \omega_\varepsilon^X = \omega_\varepsilon^X(R_j) \simeq 2^{-j\alpha}.
\end{equation}
It follows from \eqref{est.BdryDecomp} that
\begin{equation}
\begin{aligned}
    |v_\varepsilon(X)| & \lesssim \sum_{j = 0}^{L+1} \bigg(\fint_{R_j} |f(P')|^{p'_0} d\sigma(P') \bigg)^{1/p'_0} 2^{-j \alpha} \\ 
    & \lesssim \big\{ \mathcal{M}_{\partial \Omega}(|f|^{p'_0})(Q) \big\}^{1/{p'_0}},
\end{aligned}
\end{equation}
where $\mathcal{M}_{\partial \Omega}(F)$ denotes the Hardy-Littlewood maximal function on $\partial \Omega$.

Taking supremum over all $X\in \Gamma(Q)$ with $\mathrm{dist}(X,\partial \Omega) > 10\varepsilon$, we arrive at
\begin{equation}
    N_\varepsilon(v_\varepsilon)(Q) \lesssim \big\{ \mathcal{M}_{\partial \Omega}(|f|^{p'_0})(Q)\big\}^{1/{p'_0}}.
\end{equation}
Now, for any $p> p'_0$, by the $L^q$ boundedness of Hardy-Littlewood maximal function for any $q>1$, we have
\begin{equation}
    \| N_\varepsilon(v_\varepsilon) \|_{L^p(\partial \Omega)} \lesssim \bigg( \int_{\partial \Omega} \big\{ \mathcal{M}_{\partial \Omega}(|f|^{p'_0})(Q)\big\}^{p/{p'_0}} d\sigma(Q) \bigg)^{1/p} \lesssim \| f \|_{L^p(\partial \Omega)}.
\end{equation}
Note that $p = \infty$ is trivial from the maximal principle.
This ends the proof.

