    This large-scale estimate can be compared to the classical result for $\mathcal{L}_\varepsilon$-harmonic functions; see e.g. \cite{D77,D79,FKP91}.

We use the representation formula by $\mathcal{L}_\varepsilon$-harmonic measure,
\begin{equation}
    u_\varepsilon(X) = \int_{\partial \Omega} f(P) d\omega_\varepsilon^X(P).
\end{equation}
Observe that by the definition of $S_\varepsilon(f)$, we have $|f(P)| \le S_\varepsilon(f)(Q)$ for any $Q\in \Delta_\varepsilon(P)$. Since $|\Delta_\varepsilon(P)| \simeq |\Delta_\varepsilon(Q)|$, we have
$|f(P)| \lesssim \overline{S_\varepsilon(f)}(P)$.
Consequently, in view of \eqref{eq.bar.dual},
\begin{equation}
    |u_\varepsilon(X)| \lesssim \int_{\partial \Omega} \overline{S_\varepsilon(f)} d\omega_\varepsilon^X = \int_{\partial \Omega} S_\varepsilon(f) \overline{\omega}_\varepsilon^X d\sigma.
\end{equation}
Then \eqref{est.Dp} follows from this and \eqref{est.Neve} in Theorem \ref{thm.Neve<f}.

It follows that $\| S_\varepsilon(u_\varepsilon) \|_{L^p(\partial \Omega^\varepsilon)} \lesssim \| M_{4\varepsilon}(u_\varepsilon) \|_{L^p(\partial \Omega)}$, which together with \eqref{est.N<S} leads to
\begin{equation}\label{N-M}
    \| N_\varepsilon (u_\varepsilon)\|_{L^p(\partial\Omega)}
    \lesssim \| M_{4\varepsilon} (u_\varepsilon)\|_{L^p(\partial\Omega)}.
\end{equation}

\begin{equation}\label{def.Qe}
    \mathcal{Q}_\varepsilon(u)(X) = \frac{ u(X + \varepsilon e_d) - u(X)}{\varepsilon} = \frac{1}{\varepsilon} \int_{x_d}^{x_d + \varepsilon} \frac{\partial u}{\partial x_d}(x',t) dt.
