\label{lem.NT.ptws}
    Let $\varepsilon \lesssim r$ and $I_r = I_r(O)$ with $O \in \partial \Omega$. Let $u_\varepsilon$ be a solution of $-\nabla\cdot A^\varepsilon \nabla u_\varepsilon = 0$ in $T_{10r}$.
    Then for any $Q = (z',\phi(z')) \in I_r$,






    \begin{equation}\label{est.NeDue.local}
    \begin{aligned}
        \widetilde{N}_\varepsilon^r(\nabla u_\varepsilon)(Q) &\lesssim \mathcal{M}_{I_{3r}} (\widetilde{N}_\varepsilon^{3r}(\mathcal{Q}_\varepsilon(u_\varepsilon)))(Q)  + \mathcal{M}_{I_{3r}} (V_\varepsilon)(Q),
    \end{aligned}
    \end{equation}
    where
\begin{equation}\label{def.VeP}
    V_\varepsilon(P) = \fint_{0}^{11\varepsilon} |\nabla u_\varepsilon(y',\phi(y') + t)| dt, \ \text{with } P = (y',\phi(y')),
\end{equation}
    and
    \begin{equation}\label{def.MI3r}
        \mathcal{M}_{I_{3r}}f(Q) = \sup \bigg\{ \fint_{I'} |f| d\sigma: Q\in I' \subset I_{3r}\bigg\}.
    \end{equation}

Fix $Q_0 = (z',\phi(z')) \in I_r$ and $X \in \Gamma(Q_0) \cap (\Omega_{r} \setminus \Omega_{10\varepsilon})$. Let $s:= \delta(X) \le r$. 
By the interior Caccioppoli inequality,
\begin{equation}\label{est.Due2ue-E}
\begin{aligned}
    \bigg( \fint_{B(X,s/2)} |\nabla u_\varepsilon|^2 \bigg)^{1/2} & \lesssim \frac{1}{s} \bigg( \fint_{B(X,3s/5)} | u_\varepsilon - E|^2 \bigg)^{1/2} \\
    & \lesssim \frac{1}{s} \fint_{B(X,4s/5)} |u_\varepsilon - E|,
    \end{aligned}
\end{equation}
where $E$ is an arbitrary constant to be specified later.

Let $Y = (y',y_d) \in B(X, 4s/5)$.
Note that 
\begin{equation}
\begin{aligned}
    & |u_\varepsilon(y',y_d) - E| \\
    & \le |u_\varepsilon(y',y_d) - u_\varepsilon(y',y_d-\varepsilon)| +  |u_\varepsilon(y',y_d-\varepsilon) - u_\varepsilon(y',y_d-2\varepsilon)| \\
    & \qquad + \cdots + |u_\varepsilon(y',y_d-m\varepsilon) - u_\varepsilon(y',\phi(y') + h)| + |u_\varepsilon(y',\phi(y') + h) - E|,
    \end{aligned}
\end{equation}
where $m$ is an integer such that $y_d-m\varepsilon > \phi(y')+10\varepsilon \ge y_d-(m+1)\varepsilon $, and $h \in [0,\varepsilon]$ is a free parameter. On both sides taking average over $h\in [0,\varepsilon]$, we have
\begin{equation}\label{est.ue-E}
\begin{aligned}
     |u_\varepsilon(y',y_d) - E| & \le \sum_{j= 1}^{m-1} \varepsilon |\mathcal{Q}_\varepsilon(u_\varepsilon)(y',y_d - j \varepsilon)| \\
     & \qquad + \frac{1}{\varepsilon} \int_0^\varepsilon |u_\varepsilon(y',y_d-m\varepsilon) - u_\varepsilon(y',\phi(y') + h)|dh \\
     & \qquad + \frac{1}{\varepsilon} \int_0^\varepsilon |u_\varepsilon(y',\phi(y') + h) - E|dh \\
    & \le (m-1) \varepsilon \sup_{\phi(y')+10\varepsilon < t <\phi(y') + 3s} |\mathcal{Q}_\varepsilon(u_\varepsilon)(y',t)| \\
    & \qquad + \int_{\phi(y')}^{\phi(y') + 11\varepsilon} |\nabla u_\varepsilon(y',t)| dt \\
    & \qquad + \frac{1}{\varepsilon} \int_0^\varepsilon |u_\varepsilon(y',\phi(y') + h) - E| dh.
\end{aligned}
\end{equation}
Note that $m\varepsilon \simeq s$. We will write $u_\varepsilon(y',\phi(y') + h) = u_\varepsilon(Q + he_d)$ for $Q = (y', \phi(y'))$.

Integrating \eqref{est.ue-E} over $Y \in B(X,4s/5)$, we get
\begin{equation}\label{est.ue-E2}
\begin{aligned}
    & \fint_{B(X,4s/5)} |u_\varepsilon - E| \\
    & \lesssim s \fint_{I_s(x',\phi(x'))} \widetilde{N}_\varepsilon^{3r}(\mathcal{Q}_\varepsilon(u_\varepsilon)) d\sigma + \varepsilon \fint_{I_s(x',\phi(x'))} V_\varepsilon d\sigma \\
    & \qquad +  \frac{1}{\varepsilon} \int_0^\varepsilon \fint_{I_s(x',\phi(x'))} |u_\varepsilon(Q + he_d) - E| d\sigma(Q) dh,
    \end{aligned}
\end{equation}
where $V_\varepsilon$ is given by \eqref{def.VeP} and $(x',\phi(x'))$ is the vertical projection of $X = (x',x_d)$ on $\partial \Omega$.
Let $E = E_0 = \fint_{I_s(x',\phi(x'))} u_\varepsilon(Q) d\sigma(Q)$ and $E_h = \fint_{I_s(x',\phi(x'))} u_\varepsilon(Q + he_d) d\sigma(Q)$. Then by the Poincar\'{e} inequality,
\begin{equation}
    \fint_{I_s(x',\phi(x'))} |u_\varepsilon(Q + he_d) - E_h| \lesssim s \fint_{I_s(x',\phi(x'))} |\nabla_{\tan} u_\varepsilon(Q + he_d) | d\sigma(Q), 
\end{equation}
and
\begin{equation}
\begin{aligned}
    |E_h - E| & = \bigg| \fint_{I_s(x',\phi(x'))} ( u_\varepsilon(Q + he_d) - u_\varepsilon(Q)) d\sigma(Q)\bigg| \\
        & \le \fint_{I_s(x',\phi(x'))} \int_0^\varepsilon |\partial_{x_d} u_\varepsilon(Q + he_d)| dh d\sigma(Q).
\end{aligned}
\end{equation}
By these two inequalities, we have
\begin{equation}
\begin{aligned}
    & \frac{1}{\varepsilon} \int_0^\varepsilon \fint_{I_s(x',\phi(x'))} |u_\varepsilon(Q + he_d) - E| d\sigma(Q) dh \\
    & \le \fint_0^\varepsilon \fint_{I_s(x',\phi(x'))} |u_\varepsilon(Q + he_d) - E_h| d\sigma dh + \fint_0^\varepsilon |E_h - E| dh \\
    & \lesssim  s \fint_{I_s(x',\phi(x'))} \fint_0^\varepsilon |\nabla_{\tan} u_\varepsilon(Q + he_d) | dh d\sigma(Q) \\
    & \qquad + \varepsilon \fint_{I_s(x',\phi(x'))} \fint_0^\varepsilon |\partial_{x_d} u_\varepsilon(Q + he_d)| dh d\sigma(Q) \\
    & \lesssim   s \fint_{I_s(x',\phi(x'))} V_\varepsilon(Q) d\sigma(Q).
\end{aligned}
\end{equation}
Inserting this into \eqref{est.ue-E2}, we get
\begin{equation}
    \fint_{B(X,4s/5)} |u_\varepsilon - E| \lesssim s \fint_{I_s(x',\phi(x'))} \widetilde{N}_\varepsilon^{3r}(\mathcal{Q}_\varepsilon(u_\varepsilon)) d\sigma + s \fint_{I_s(x',\phi(x'))} V_\varepsilon d\sigma.
\end{equation}
Using the observation that $I_s(x',\phi(x')) \subset I_{2s}(Q_0) \subset I_{3r}(O)$ due to $X\in \Gamma(Q_0) \cap \Omega_r$, we have
\begin{equation}
    \frac{1}{s}\fint_{B(X,4s/5)} |u_\varepsilon - E| \lesssim \mathcal{M}_{I_{3r}} (\widetilde{N}_\varepsilon^{3r}(\mathcal{Q}_\varepsilon(u_\varepsilon)))(Q_0) + \mathcal{M}_{I_{3r}} (V_\varepsilon)(Q_0),
\end{equation}
which combined with \eqref{est.Due2ue-E} gives the desired estimate.

