\label{lem.NeQe}
    Let $u_\varepsilon$ be a solution of $-\nabla\cdot A^\varepsilon \nabla u_\varepsilon = 0$ in $T_{5r}$ with $r \ge 10 \varepsilon$. Then
    \begin{equation}
    \int_{I_{r}} \widetilde{N}_\varepsilon^{r} (\mathcal{Q}_\varepsilon(u_\varepsilon))^2 d\sigma \lesssim \frac{1}{\varepsilon} \int_{T_{5r} \cap \Omega_{5\varepsilon}} |\nabla u_\varepsilon|^2 + \int_{T_{5r}} |\nabla u_\varepsilon|^2.
\end{equation}

By the estimate \eqref{N-M} applied to $\mathcal{Q}_\varepsilon(u_\varepsilon)$ in $T_{t}$ for every $t \in [4r, 5r]$, we have
\begin{equation}
    \int_{I_{r}} \widetilde{N}_\varepsilon^{r} (\mathcal{Q}_\varepsilon(u_\varepsilon))^2 d\sigma \lesssim \int_{\partial T_{t}} |N_\varepsilon(\mathcal{Q}_\varepsilon(u_\varepsilon))|^2 \lesssim \frac{1}{\varepsilon} \int_{T_{t,4\varepsilon}} |\mathcal{Q}_\varepsilon(u_\varepsilon)|^2.
\end{equation}
Using \eqref{def.Qe}, we see that 
\begin{equation}
    \frac{1}{\varepsilon} \int_{T_{t,4\varepsilon}} |\mathcal{Q}_\varepsilon(u_\varepsilon)|^2 \lesssim \frac{1}{\varepsilon} \int_{T_{t+\varepsilon, 5\varepsilon}} |\nabla u_\varepsilon|^2. 
\end{equation}
Combining the last two inequalities, we obtain
\begin{equation}
    \int_{I_{r}} \widetilde{N}_\varepsilon^{r} (\mathcal{Q}_\varepsilon(u_\varepsilon))^2 d\sigma \lesssim \frac{1}{\varepsilon} \int_{T_{t+\varepsilon, 5\varepsilon}} |\nabla u_\varepsilon|^2.
\end{equation}
Note that the left-hand side is independent of $t$ as $t$ varies in $[4r,5r]$. Thus, we integrate the above inequality in $t$ over $[4r,5r - \varepsilon]$ and use Fubini's Theorem to obtain
\begin{equation}
    \int_{I_{r}} \widetilde{N}_\varepsilon^{r} (\mathcal{Q}_\varepsilon(u_\varepsilon))^2 d\sigma \lesssim \frac{1}{\varepsilon} \int_{T_{5r} \cap \Omega_{5\varepsilon}} |\nabla u_\varepsilon|^2 + \frac{1}{r} \int_{T_{5r}} |\nabla u_\varepsilon|^2.
\end{equation}
The proof is complete.

\label{coro.localR2}
    Let $u_\varepsilon$ be a solution of $-\nabla\cdot A^\varepsilon \nabla u_\varepsilon =0 $ in $T_{15r}$ with $r \ge 10\varepsilon$. Then
    \begin{equation}\label{est.NeDue.localL2}
    \int_{I_{r}} \widetilde{N}_\varepsilon^{r}(\nabla u_\varepsilon)^2 d\sigma  \lesssim \frac{1}{\varepsilon} \int_{T_{15r} \cap \Omega_{20\varepsilon}} |\nabla u_\varepsilon|^2 + \frac{1}{r}\int_{T_{15r}} |\nabla u_\varepsilon|^2.
    \end{equation}

First of all, by rotation and a localization argument as in Subsection \ref{subsec.localization}, the local estimate of large-scale nontangential maximal function \eqref{est.NeDue.localL2}, established in a graph domain, can be transferred into a form in a bounded Lipschitz domain, i.e.,
\begin{equation}
\int_{\Delta_{r}} \widetilde{N}_\varepsilon^{r}(\nabla u_\varepsilon)^2 d\sigma \lesssim \frac{1}{\varepsilon} \int_{D_{15r} \cap \Omega_{20\varepsilon}} |\nabla u_\varepsilon|^2 + \frac{1}{r}\int_{D_{15r}} |\nabla u_\varepsilon|^2. 
\end{equation}
By taking $r \simeq r_0$ as in Subsection \ref{subsec.localization} and a covering argument, we have
\begin{equation}\label{est.RN.L2}
    \| \widetilde{N}_\varepsilon(\nabla u_\varepsilon) \|_{L^2(\partial \Omega)} \lesssim \bigg( \frac{1}{\varepsilon} \int_{\Omega_{20\varepsilon} } |\nabla u_\varepsilon|^2 \bigg)^{1/2} + \| \nabla u_\varepsilon \|_{L^2(\Omega)}.
\end{equation}
Now,  if $u_\varepsilon$ satisfies \eqref{Rp}, then the energy estimate implies
\begin{equation}
    \| \nabla u_\varepsilon \|_{L^2(\Omega)} \lesssim  \|  f \|_{H^1(\partial \Omega)}.
\end{equation}
The large-scale Rellich estimate \eqref{eq.LSRellich-D} implies
\begin{equation}
    \bigg( \frac{1}{\varepsilon} \int_{\Omega_{20\varepsilon} } |\nabla u_\varepsilon|^2 \bigg)^{1/2} \lesssim  \|  f \|_{H^1(\partial \Omega)}.
\end{equation}
Combining these estimates together, we obtain \eqref{est.Rp} for $p = 2$. Similarly, for the Neumann problem we apply the energy estimate and the large-scale Rellich estimate \eqref{eq.LSRellich-N} to the right-hand side of \eqref{est.RN.L2} to obtain \eqref{est.Np} for $p = 2$.

Let $u_\varepsilon$ be a solution of $-\nabla \cdot A^\varepsilon \nabla u_\varepsilon = 0$ in $T_{2r}$. Then for $r> 10\varepsilon$,
\begin{equation}\label{est.localR2}
    \int_{I_r} \widetilde{N}^r_\varepsilon(\nabla u_\varepsilon)^2 d\sigma \lesssim \int_{I_{2r}}  |\nabla_{\tan} u_\varepsilon|^2 d\sigma + \frac{1}{r}\int_{T_{2r}} |\nabla u_\varepsilon|^2,
\end{equation}
and
\begin{equation}\label{est.localN2}
    \int_{I_r} \widetilde{N}^r_\varepsilon(\nabla u_\varepsilon)^2 d\sigma \lesssim \int_{I_{2r}}  \Big|\frac{\partial u_\varepsilon}{\partial \nu_\varepsilon}\Big|^2 d\sigma + \frac{1}{r}\int_{T_{2r}} |\nabla u_\varepsilon|^2.
\end{equation}

\label{prop.R1}
    If $f\in C^1(\partial \Omega)$ and $u_\varepsilon$ is a solution of $\mathcal{L}_\varepsilon(u_\varepsilon)=0$ in $\Omega$ with
    $u_\varepsilon=f$ on $\partial\Omega$, then
\begin{equation}\label{est.R1}
    \| \widetilde{N}_\varepsilon(\nabla u_\varepsilon) \|_{L^1(\partial \Omega)} \lesssim \| \nabla_{\tan} f \|_{H^1_{\rm at}(\partial \Omega)}.
\end{equation}

\label{lem.QinRj}
    For $Q\in R_j$, we have
    \begin{equation}\label{est.L1inRj}
        \widetilde{N}_\varepsilon(\nabla u_\varepsilon)(Q) \lesssim \widetilde{N}_\varepsilon^{cr_j}(\nabla u_\varepsilon)(Q) + \frac{r^\alpha}{r_j^{d-1+\alpha}},
    \end{equation}
    where $c\in (0,1)$ is a constant independent of $r_j$ and $\varepsilon$.
    Moreover, if $cr_j \le 10\varepsilon$, then the first term on the right-hand side of \eqref{est.L1inRj} does not appear.

Let $X \in \Gamma(Q)$ with $\delta(X) \ge \max \{ 10\varepsilon, cr_j \}$. By the Caccioppoli inequality,
\begin{equation}\label{est.R1.NeDue2ue}
    \bigg( \fint_{B(X,\delta(X)/2)} |\nabla u_\varepsilon|^2 \bigg)^{1/2} \lesssim \delta(X)^{-1} \bigg( \fint_{B(X,\frac35\delta(X))} | u_\varepsilon|^2 \bigg)^{1/2}.
\end{equation}
Note that for each $Y\in B(X,\frac35 \delta(X))$, we still have $\delta(Y) \ge \frac25 \max\{ 10\varepsilon, cr_j \}$. By using the representation by $\mathcal{L}_\varepsilon$-harmonic measure \eqref{eq.hm}, we have
\begin{equation}\label{est.ptwise.uY}
\begin{aligned}
    |u_\varepsilon(Y)| & \le \| f \|_{L^\infty(\Delta_r(P))} \omega^Y_\varepsilon(\Delta_r(P)) \lesssim r^{d-2} \omega^Y_\varepsilon(\Delta_r(P)) \\
    & \simeq G_\varepsilon(Y, A_r(P)) \lesssim   \frac{r^\alpha }{|Y-P|^{d-2+\alpha}},
\end{aligned}
\end{equation}
where we have used Proposition \ref{prop.hmBasics} \ref{item.w=G} and \ref{item.G.Holder} in the last inequality.
Obviously, $|Y-P| \ge \delta(Y) \ge \frac25 cr_j$. Hence, for every $Y \in B(X, \frac35 \delta(X))$,
\begin{equation}
    |u(Y)| \lesssim \frac{ r^\alpha}{ r_j^{d-2+\alpha}}.
\end{equation}
Combining this with \eqref{est.R1.NeDue2ue}, we obtain that for any $X\in \Gamma(Q)$ and $\delta(X) \ge \max\{ 10\varepsilon, r_j\}$,
\begin{equation}
    \bigg( \fint_{B(X,\delta(X)/2)} |\nabla u_\varepsilon|^2 \bigg)^{1/2} \lesssim \frac{ r^\alpha}{ r_j^{d-1+\alpha}}.
\end{equation}
Thus, if $r_j \ge 10\varepsilon$, then we have \eqref{est.L1inRj}. If $r_j < 10\varepsilon$, we simply do not have the term $N_\varepsilon^{r_j}(\nabla u_\varepsilon)(Q)$ on the right-hand side.

It suffices to prove \eqref{est.DeuL1<1}.
We show on each $R_j$ with $1\le j\le L+1$,
\begin{equation}\label{est.rjPj}
    \int_{R_j} |\widetilde{N}_\varepsilon(\nabla u_\varepsilon)| d\sigma \lesssim  \Big( \frac{r}{r_j} \Big)^\alpha.
\end{equation}    

If $c r_j \le 10 \varepsilon$, then by Lemma \ref{lem.QinRj} and an integration over $R_j$, we directly get
\begin{equation}
    \int_{R_j} |\widetilde{N}_\varepsilon(\nabla u_\varepsilon)| d\sigma \lesssim \int_{R_j } \frac{ r^\alpha}{ r_j^{d-1+\alpha}} d\sigma \lesssim \Big( \frac{r}{r_j} \Big)^\alpha.
\end{equation}

If $c r_j > 10\varepsilon$, by Lemma \ref{lem.QinRj},
\begin{equation}\label{est.intof.rj>e}
    \int_{R_j} \widetilde{N}_\varepsilon(\nabla u_\varepsilon) d\sigma \lesssim \int_{R_j} \widetilde{N}_\varepsilon^{c r_j}(\nabla u_\varepsilon) d\sigma + \Big( \frac{r}{r_j} \Big)^\alpha.
\end{equation}
Note that $u_\varepsilon = 0$ on $\partial\Omega \setminus \Delta (P, r)$. We decompose $R_j$ into a union of $\Delta_{cr_j}(Q_k)$ with finite overlaps. As $\Omega$ is Lipschitz, the number of such $\Delta_{cr_j}(Q_k)$ depends only on $\Omega$. Then by \eqref{est.localR2} and the Caccioppoli inequality,
\begin{equation}\label{est.localNrj}
    \int_{\Delta_{cr_j}(Q_k)} \widetilde{N}_\varepsilon^{cr_j}(\nabla u_\varepsilon)^2 d\sigma \lesssim \frac{1}{r_j} \int_{D_{2c r_j}(Q_k)} |\nabla u_\varepsilon|^2 \lesssim \frac{1}{r_j^3} \int_{D_{3c r_j}(Q_k)} |u_\varepsilon|^2.
\end{equation}
Using the same argument as Lemma \ref{lem.QinRj}, for $X\in D_{3cr_j}(Q_k)$,
\begin{equation}\label{est.ptwise.uY1}
    |u_\varepsilon(X)| \lesssim \frac{r^\alpha}{r_j^{d-2+\alpha}}.
\end{equation}
Inserting this into \eqref{est.localNrj}, we get
\begin{equation}
    \int_{\Delta_{cr_j}(Q_k)} \widetilde{N}_\varepsilon^{cr_j}(\nabla u_\varepsilon)^2 d\sigma \lesssim \frac{r^{2\alpha}}{r_j^{d-1+2\alpha}}.
\end{equation}
Summing over $k$ and combining this with \eqref{est.intof.rj>e} and the H\"{o}lder inequality, we arrive at \eqref{est.rjPj}.

Consequently, by \eqref{est.Delta10r}, \eqref{eq.Omega.decomp} and \eqref{est.rjPj}, we have
\begin{equation}
    \int_{\partial \Omega} |\widetilde{N}_\varepsilon(\nabla u_\varepsilon)| \le \int_{\Delta_{10r}(P)}|\widetilde{N}_\varepsilon(\nabla u_\varepsilon)| + \sum_{j}  \int_{R_j} |\widetilde{N}_\varepsilon(\nabla u_\varepsilon)| d\sigma \lesssim 1.
\end{equation}
The proof is complete.

For any $g\in L_0^2(\partial \Omega)$, the weak solution of \eqref{Np} satisfying $\int_{\partial \Omega} u_\varepsilon d\sigma = 0$ is given by
\begin{equation}\label{eq.NP}
    u_\varepsilon(X) = \int_{\partial \Omega} \mathcal{N}_\varepsilon(X,Q) g(Q) d\sigma(Q).
\end{equation}

\label{prop.N1}
    If $g \in H_{\rm at}^1(\partial \Omega)$ with $\int_{\partial \Omega} g d\sigma = 0$, then the solution given by \eqref{eq.NP} satisfies
\begin{equation}\label{est.NP.L1}
    \| \widetilde{N}_\varepsilon(\nabla u_\varepsilon) \|_{L^1(\partial \Omega)} \lesssim \| g \|_{H^1_{\rm at}(\partial \Omega)}.
\end{equation}

It suffices to consider an atom $g$ supported in $\Delta_r(P)$ for some $P\in \partial \Omega$ and $|g| \le Cr^{1-d}$, and prove
\begin{equation}\label{est.N1}
    \| \widetilde{N}_\varepsilon(\nabla u_\varepsilon) \|_{L^1(\partial \Omega)} \lesssim 1.
\end{equation}

Similar to the regularity problem, in $\Delta_{10r}(P)$, we apply the $L^2$ estimate for the Neumann problem to obtain
\begin{equation}\label{est.N1.P0}
    \int_{\Delta_{10r}(P)} |N_\varepsilon(\nabla u_\varepsilon)| \lesssim 1.
\end{equation}
We decompose $\partial \Omega \setminus \Delta_{10r}(P)$ as in \eqref{eq.Omega.decomp}. On each $R_j$, we can show
\begin{equation}\label{est.N1.Pj}
    \int_{R_j} |N_\varepsilon(\nabla u_\varepsilon)| \lesssim \Big( \frac{r}{r_j} \Big)^\alpha.
\end{equation}
Comparing the regularity problem, the only difference is the pointwise estimate of $u_\varepsilon(Y)$ in \eqref{est.ptwise.uY} for $Y \in \Gamma(Q')$ with $Q' \in R_j$. Instead of using the $\mathcal{L}_\varepsilon$-harmonic measure, we now use the representation of Neumann function. Due to the fact $\int_{\partial \Omega} g d\sigma = 0$,
\begin{equation}
    u_\varepsilon(Y) = \int_{\Delta_r(P)} (\mathcal{N}_\varepsilon(Y,Q) - \mathcal{N}_\varepsilon(Y,P)) g(Q) d\sigma(Q).
\end{equation}
By \eqref{est.NF.Holder}, for $Y\in \Gamma(Q'), Q'\in R_j$,
\begin{equation}
    |u_\varepsilon(Y)| \lesssim \int_{\Delta_r(P)} \frac{r^\alpha}{r_j^{d-2+\alpha}} r^{1-d} d\sigma \lesssim \frac{r^\alpha}{r_j^{d-2+\alpha}},
\end{equation}
which is the same as \eqref{est.ptwise.uY1}. Thus, by the interior Caccioppoli inequality 
\begin{equation}
    \widetilde{N}_\varepsilon(\nabla u_\varepsilon)(Q') \lesssim \widetilde{N}_\varepsilon^{cr_j}(\nabla u_\varepsilon)(Q') + \frac{r^\alpha}{r_j^{d-1+\alpha}},
\end{equation}
for any $Q'\in \Delta_{r_j}(P_j)$, which together with \eqref{est.localN2} yields \eqref{est.N1.Pj}. Summing \eqref{est.N1.P0} and \eqref{est.N1.Pj} over $j$, we obtain \eqref{est.N1}.

\label{lem.RH}
Let $u_\varepsilon$ be a solution of $\mathcal{L}_\varepsilon(u_\varepsilon) = 0$ in $T_{4R}$ satisfying either $u_\varepsilon = 0$ or $\frac{\partial u_\varepsilon}{\partial \nu_\varepsilon} = 0$ on $I_{4R}$ with $R \ge  100\varepsilon$. Then there exists $p_0 > 2$ such that
\begin{equation}\label{est.ReverseHolder.Nhat}
    \bigg( \fint_{I_R} | \widehat{N}_\varepsilon (\nabla u_\varepsilon)|^{p_0} d\sigma \bigg)^{1/{p_0}} \lesssim \bigg( \fint_{I_{2R}} |\widehat{N}_\varepsilon(\nabla u_\varepsilon)|^{2} d\sigma \bigg)^{1/{2}}.
\end{equation}

This is proved by the self-improving property of the reverse H\"{o}lder inequality.
Let $P\in I_R$ and $I_{4r}(P) \subset I_{2R}, r>0$. We only need to prove
\begin{equation}\label{est.ReverseHolder.L2L1}
    \bigg( \fint_{I_r(P)} |\widehat{N}_\varepsilon(\nabla u_\varepsilon)|^2 d\sigma  \bigg)^{1/2} \lesssim \bigg( \fint_{I_{3r}(P)} |\widehat{N}_\varepsilon(\nabla u_\varepsilon)|^{p_*} d\sigma \bigg)^{p_*},
\end{equation}
where $p_* = \frac{2d}{d+2} < 2$. Then \eqref{est.ReverseHolder.Nhat} is a straightforward corollary of the self-improving property of the reverse H\"{o}lder inequality.

\textbf{Case 1: $r<50\varepsilon$.} We will show that for this case, a reverse H\"{o}lder inequality holds for $\widehat{N}_\varepsilon(\nabla u_\varepsilon)$ by its definition, irrelevant to the equation. To see this,
we first claim that if $r<50\varepsilon$, for each $Q \in I_r(P)$,
\begin{equation}\label{est.claim-1}
    \widetilde{N}_\varepsilon(\nabla u_\varepsilon)(Q) \lesssim \fint_{I_{r}(Q)} \widetilde{N}_\varepsilon(\nabla u_\varepsilon) d\sigma.
\end{equation}
To show the claim, we fix $Q$ and let $X\in \Gamma(Q)$ be such that $\delta(X) > 10\varepsilon$ and $\widetilde{N}_\varepsilon(\nabla u_\varepsilon)(Q)$ is attained at $X$, namely,
\begin{equation}
    \widetilde{N}_\varepsilon(\nabla u_\varepsilon)(Q) \simeq \bigg( \fint_{B(X,\delta(X)/2)} |\nabla u_\varepsilon|^2 \bigg)^{1/2}.
\end{equation}
Now, in view of the definition of the cone $\Gamma(Q)$ in graph domain \eqref{def.Gamma.graph}, we see that there exists a subset $E \subset I_r(Q)$ with $|E| \simeq |I_r(Q)|$ such that for each $Q' \in E$, $X \in \Gamma(Q')$. This implies $\widetilde{N}_\varepsilon(\nabla u_\varepsilon)(Q) \lesssim \widetilde{N}_\varepsilon(\nabla u_\varepsilon)(Q')$ for each $Q'\in E$. Hence,
\begin{equation}
    \widetilde{N}_\varepsilon(\nabla u_\varepsilon)(Q) \lesssim \frac{1}{|E|} \int_{E} \widetilde{N}_\varepsilon(\nabla u_\varepsilon) d\sigma \lesssim \fint_{I_r(Q)} \widetilde{N}_\varepsilon(\nabla u_\varepsilon) d\sigma,
\end{equation}
which proves the claim \eqref{est.claim-1}. 

The claim \eqref{est.claim-1} then easily yields
\begin{equation}\label{est.L2reverse-1}
    \bigg( \fint_{I_r(P)} |\widetilde{N}_\varepsilon(\nabla u_\varepsilon)|^2 d\sigma  \bigg)^{1/2} \lesssim \fint_{I_{2r}(P)} \widetilde{N}_\varepsilon(\nabla u_\varepsilon) d\sigma.
\end{equation}

Next, by a property of the average operator \eqref{est.Mef-Bs-1} in Proposition \ref{prop.Mef-Bs} (the property is proved for $M_\varepsilon$, but it holds for $M_{10\varepsilon}^\star$ as well), for any $s \lesssim 10 \varepsilon$, we have
\begin{equation}
    M_{10\varepsilon}^\star(\nabla u_\varepsilon)(Q) \lesssim \fint_{I_s(Q)} M_{10\varepsilon}^\star(\nabla u_\varepsilon) d\sigma.
\end{equation}
Taking $s = r < 50\varepsilon$ and any $Q\in I_r(P)$, we have
\begin{equation}\label{est.L2reverse-2}
    \bigg( \fint_{I_r(P)} |M_{10\varepsilon}^\star(\nabla u_\varepsilon)|^2 d\sigma  \bigg)^{1/2} \lesssim \fint_{I_{2r}(P)} M_{10\varepsilon}^\star(\nabla u_\varepsilon) d\sigma.
\end{equation}
Combining \eqref{est.L2reverse-1} and \eqref{est.L2reverse-2}, we obtain, for $r<50\varepsilon$,
\begin{equation}
    \bigg( \fint_{I_r(P)} |\widehat{N}_\varepsilon(\nabla u_\varepsilon)|^2 d\sigma  \bigg)^{1/2} \lesssim \fint_{I_{2r}(P)} \widehat{N}_\varepsilon(\nabla u_\varepsilon) d\sigma.
\end{equation}

\textbf{Case 2: $r>50\varepsilon$.} In this large-scale case, we first note that for each $Q\in \Delta_r$,
\begin{equation}\label{est.case2}
    \widetilde{N}_\varepsilon(\nabla u_\varepsilon)(Q) \lesssim \fint_{I_{2r}(P)} \widetilde{N}_\varepsilon(\nabla u_\varepsilon) d\sigma + \widetilde{N}_\varepsilon^r(\nabla u_\varepsilon)(Q).
\end{equation}
Indeed, if  $\widetilde{N}_\varepsilon(\nabla u_\varepsilon)(Q)$ is reached at a point $X$ with $\delta(X) > r$, then, for the same reason as in Case 1, $\widetilde{N}_\varepsilon(\nabla u_\varepsilon)(Q)$ is bounded by the first term of \eqref{est.case2}. If $\widetilde{N}_\varepsilon(\nabla u_\varepsilon)(Q)$ is attained at a point $X$ with $\delta(X)<r$, then it is clearly bounded by the second term of \eqref{est.case2}.


We estimate the second term of \eqref{est.case2}.
Using either the local $(R)_2$ estimate \eqref{est.localR2} if $u_\varepsilon = 0$ on $I_{4R}$ or the local $(N)_2$ estimate \eqref{est.localN2} if $\frac{\partial u_\varepsilon}{\partial \nu_\varepsilon} = 0$ on $I_{4R}$,
\begin{equation}\label{est.RH-1}
\begin{aligned}
    \bigg( \fint_{I_r(P)} \widetilde{N}_\varepsilon^r(\nabla u_\varepsilon)^2 d\sigma \bigg)^{1/2} 

    &\lesssim  \bigg( \fint_{T_{2r}(P)} |\nabla u_\varepsilon|^2 \bigg)^{1/2} \\
    & \lesssim  \frac{1}{r} \bigg( \fint_{T_{3r}(P)} |u_\varepsilon|^2 \bigg)^{1/2} \\
    & \lesssim  \bigg( \fint_{T_{3r}(P)} |\nabla u_\varepsilon|^{p_*} \bigg)^{1/p_*},
\end{aligned}
\end{equation}
where we have used the Caccioppoli inequality and Sobolev-Poincar\'{e} inequality and $1/p_* - 1/d = 1/2$. Note that in the case $\frac{\partial u_\varepsilon}{\partial \nu_\varepsilon}=0$, we need to replace $u_\varepsilon$ by $u_\varepsilon-\fint_{T_{3r}(P)} u_\varepsilon$ in \eqref{est.RH-1}.

Now we decompose the last integral into two parts
\begin{equation}
\begin{aligned}\label{est.T3r.p*}
    \bigg( \fint_{T_{3r}(P)} |\nabla u_\varepsilon|^{p_*} \bigg)^{1/p_*} & \lesssim \bigg( \frac{1}{r^d} \int_{T_{3r}(P) \cap \{ \delta(X) > 10\varepsilon \}} |\nabla u_\varepsilon|^{p_*} \bigg)^{1/p_*} \\
    & \qquad + \bigg( \frac{1}{r^d} \int_{T_{3r}(P) \cap \{ \delta(X) < 10\varepsilon \}} |\nabla u_\varepsilon|^{p_*} \bigg)^{1/p_*}.
    \end{aligned}
\end{equation}
Note that the projection $T_{3r}$ on $\partial \Omega$ is $I_{3r}$. We point out that the average operator $M_{10\varepsilon}^\star$ is introduced in the modified nontangential maximal function in order to handle the boundary layer term in \eqref{est.T3r.p*} that cannot be avoided in our large-scale analysis. In view of the definition of  $\widetilde{N}_\varepsilon(\nabla u_\varepsilon)$, if $X \in T_{3r} \cap \{ \delta(X) > 10\varepsilon \}$ has the projection $Q \in I_{3r}$, then by the large-scale Lipschitz estimate 
\begin{equation}
    M_\varepsilon(\nabla u_\varepsilon)(X) \lesssim \bigg( \fint_{B(X, \delta(X)/2)} |\nabla u_\varepsilon|^2 \bigg)^{1/2} \lesssim  \widetilde{N}_\varepsilon(\nabla u_\varepsilon)(Q).
\end{equation}
Thus, by a property of $M_\varepsilon$ in \eqref{est.f<Mef} of Proposition \ref{prop.A1} and Fubini's Theorem, we have
\begin{equation}\label{est.T3r.int}
\begin{aligned}
    \bigg( \frac{1}{r^d} \int_{T_{3r}(P) \cap \{ \delta(X) > 10\varepsilon \}} |\nabla u_\varepsilon|^{p_*} \bigg)^{1/p_*} & \lesssim \bigg( \frac{1}{r^d} \int_{T_{3r}(P) \cap \{ \delta(X) > 10\varepsilon \}} |M_\varepsilon(\nabla u_\varepsilon)|^{p_*} \bigg)^{1/p_*} \\
    & \lesssim \bigg( \fint_{I_{3r}(P)} |\widetilde{N}_\varepsilon(\nabla u_\varepsilon)|^{p_*} d\sigma \bigg)^{1/p_*}.
\end{aligned}
\end{equation}
Moreover, by Fubini's Theorem and H\"{o}lder inequality,
\begin{equation}\label{est.T3r.layer}
\begin{aligned}
    & \bigg( \frac{1}{r^d} \int_{T_{3r}(P) \cap \{ \delta(X) < 10\varepsilon \}} |\nabla u_\varepsilon|^{p_*} \bigg)^{1/p_*} \\
    & \lesssim \bigg( \frac{\varepsilon}{r^d} \int_{I_{3r}(P)} \fint_{T_{10\varepsilon}^\star(Q)} |\nabla u_\varepsilon|^{p_*} dX d\sigma(Q) \bigg)^{1/p_*} \\
    & \lesssim \bigg( \frac{\varepsilon}{r^d} \int_{I_{3r}(P)} \bigg( \fint_{T_{10\varepsilon}^\star(Q)} |\nabla u_\varepsilon|^{2} dX \bigg)^{p_*/2} d\sigma(Q) \bigg)^{1/p_*} \\
    & \lesssim \bigg( \frac{\varepsilon}{r} \fint_{I_{3r}(P)} |M_{10\varepsilon}^\star(\nabla u_\varepsilon)|^{p_*} d\sigma \bigg)^{1/p_*}.
    \end{aligned}
\end{equation}
Taking both \eqref{est.T3r.int} and \eqref{est.T3r.layer} into \eqref{est.T3r.p*}, we have
\begin{equation}\label{est.T3r-I3r}
    \bigg( \fint_{T_{3r}(P)} |\nabla u_\varepsilon|^{p_*} \bigg)^{1/p_*} \lesssim \bigg( \fint_{I_{3r}(P)} \widehat{N}_\varepsilon(\nabla u_\varepsilon)^{p_*} d\sigma \bigg)^{1/p_*},
\end{equation}
which together with \eqref{est.RH-1} yields
\begin{equation}\label{est.tNe-hNe}
    \bigg( \fint_{I_r(P)} \widetilde{N}_\varepsilon(\nabla u_\varepsilon)^2 d\sigma \bigg)^{1/2} \lesssim \bigg( \fint_{I_{3r}(P)} \widehat{N}_\varepsilon(\nabla u_\varepsilon)^{p_*} d\sigma \bigg)^{1/p_*}.
\end{equation}

To handle $M_{10\varepsilon}^\star(\nabla u_\varepsilon)$, by the $L^2$ Rellich estimate in $T_{4r}(P)$ for either the regularity problem or Neumann problem, we obtain
\begin{equation}
\begin{aligned}
    \bigg( \fint_{I_r(P)} | M_{10\varepsilon}^\star(\nabla u_\varepsilon)|^2 d\sigma \bigg)^{1/2} & \lesssim 
    \bigg( \frac{1}{\varepsilon r^{d-1}} \int_{T_{3r/2} \cap \Omega_{10\varepsilon} } |\nabla u_\varepsilon|^2 \bigg)^{1/2} \\
    & \lesssim \bigg( \fint_{T_{2r}} |\nabla u_\varepsilon|^2 \bigg)^{1/2} \\
    & \lesssim \bigg( \fint_{I_{3r}} \widehat{N}_\varepsilon(\nabla u_\varepsilon)^{p_*} d\sigma \bigg)^{1/p_*},
    \end{aligned}
\end{equation}
where we have used the combined estimate of \eqref{est.RH-1} and \eqref{est.T3r-I3r} in the last inequality.
This and \eqref{est.tNe-hNe} together give \eqref{est.ReverseHolder.L2L1} for the case $r>50\varepsilon$.



Consequently, we have proved the reverse H\"{o}lder inequality \eqref{est.ReverseHolder.L2L1} for all $I_{4r}(P) \subset I_{2R}$ and $r>0$, as desired.

\begin{equation}\label{est.T3r.layer}
\begin{aligned}
    & \bigg( \frac{1}{r^d} \int_{T_{3r}(P) \cap \{ \delta(X) < 10\varepsilon \}} |\nabla u_\varepsilon|^{p_*} \bigg)^{1/p_*} \\
    & \lesssim \bigg( \frac{\varepsilon}{r^d} \int_{I_{3r}(P)} \fint_{T_{10\varepsilon}^\star(Q)} |\nabla u_\varepsilon|^{p_*} dX d\sigma(Q) \bigg)^{1/p_*} \\
    & \lesssim \bigg( \frac{\varepsilon}{r^d} \int_{I_{3r}(P)} \bigg( \fint_{T_{10\varepsilon}^\star(Q)} |\nabla u_\varepsilon|^{2} dX \bigg)^{p_*/2} d\sigma(Q) \bigg)^{1/p_*} \\
    & \lesssim \bigg( \frac{\varepsilon}{r} \fint_{I_{3r}(P)} |M_{10\varepsilon}^\star(\nabla u_\varepsilon)|^{p_*} d\sigma \bigg)^{1/p_*}.
    \end{aligned}
\end{equation}

\begin{equation}
\begin{aligned}
    \bigg( \fint_{I_r(P)} | M_{10\varepsilon}^\star(\nabla u_\varepsilon)|^2 d\sigma \bigg)^{1/2} & \lesssim 
    \bigg( \frac{1}{\varepsilon r^{d-1}} \int_{T_{3r/2} \cap \Omega_{10\varepsilon} } |\nabla u_\varepsilon|^2 \bigg)^{1/2} \\
    & \lesssim \bigg( \fint_{T_{2r}} |\nabla u_\varepsilon|^2 \bigg)^{1/2} \\
    & \lesssim \bigg( \fint_{I_{3r}} \widehat{N}_\varepsilon(\nabla u_\varepsilon)^{p_*} d\sigma \bigg)^{1/p_*},
    \end{aligned}
\end{equation}

We first prove a localized result in a graph domain. Let $u_\varepsilon$ be a solution of $\mathcal{L}_\varepsilon(u_\varepsilon) = 0$ in $T_{4R}$ satisfying $u_\varepsilon = f$ in $I_{4R}$ with $R \ge 1000\varepsilon$. Then we show that there exists $\delta > 0$ such that for any $p\in (2, 2+\delta)$,
\begin{equation}\label{est.RpInTR}
\begin{aligned}
     & \bigg( \fint_{I_R} | \widetilde{N}_\varepsilon (\nabla u_\varepsilon)|^{p} d\sigma \bigg)^{1/{p}} \\
     & \lesssim \bigg( \fint_{I_{3R}} |\widetilde{N}_\varepsilon(\nabla u_\varepsilon)|^{2} d\sigma \bigg)^{1/{2}} + \bigg( \fint_{I_{4R}\cap \Omega_{10\varepsilon}} |\nabla u_\varepsilon|^{2} d\sigma \bigg)^{1/{2}} + \bigg( \fint_{I_{4R}} |\nabla_{\tan} f|^{p} d\sigma \bigg)^{1/p}. 
\end{aligned}
\end{equation}

We apply the real-variable argument. Let $ I_r(P) \subset I_R$ with $4r < R$ and $r>100\varepsilon$. Let $\phi \in C_0^1(B_{5r}(P))$ be the cut-off function such that $\phi = 1$ in $B_{4r}(P)$ and $|\nabla \phi| \lesssim r^{-1}$. Let $\lambda = \fint_{I_{4r}} f d\sigma$. Then we define $f_1 = (f-\lambda)\phi$ and let $u_\varepsilon^1$ be the solution of $\mathcal{L}_\varepsilon(u_\varepsilon^1) = 0$ and $u_\varepsilon^1 = f_1 \mathbbm{1}_{I_{5r}(P)}$ on $\partial T_{4R}$. Decompose $u_\varepsilon - \lambda = u_\varepsilon^1 + u_\varepsilon^2$ and note that $\nabla u_\varepsilon = \nabla u_\varepsilon^1 + \nabla u_\varepsilon^2$.

Let $F = \widehat{N}_\varepsilon(\nabla u_\varepsilon), F_{I_r} = \widehat{N}_\varepsilon(\nabla u^1_\varepsilon)$ and $R_{I_r} =\widehat{N}_\varepsilon(\nabla u_\varepsilon^2)$. By applying the $(R)_2$ in the Lipschitz domain $T_{4R}$ and the $L^2$ Rellich estimate \eqref{eq.LSRellich-D}, we have
\begin{equation}
\begin{aligned}
    \fint_{I_{2r}(P)} |F_{I_{r}}|^2 & \lesssim \frac{1}{|I_{2r}(P)|} \int_{I_{4r}} |\widehat{N}_\varepsilon(\nabla u^1_\varepsilon)|^2 \\
    & \lesssim \frac{1}{|I_{2r}(P)|} \int_{ I_{4r}} |\widetilde{N}_\varepsilon(\nabla u^1_\varepsilon)|^2 + \frac{1}{|I_{2r}(P)|\varepsilon} \int_{T_{5r}(P) \cap \Omega_{10\varepsilon}} |\nabla u^1|^2 \\
    &\lesssim \fint_{I_{5r}(P)} |\nabla_{\tan}((f-\lambda)\phi)|^2 \\
    & \lesssim \fint_{I_{5r}(P)} |\nabla_{\tan} f|^2,
\end{aligned}
\end{equation}
where we have used 
\begin{equation}\label{est.Mstar-Layer}
    \int_{I_{4r}} M_{10\varepsilon}^\star(F)^2 \lesssim \frac{1}{\varepsilon} \int_{T_{5r}(P) \cap \Omega_{10\varepsilon}} |F|^2
\end{equation}
in the second inequality and
the Poincar\'{e} inequality in the last inequality.


For $R_{I_r}$, note that $u_\varepsilon^2 = 0$ on $I_{4r}(P)$. Then, Lemma \ref{lem.RH} yields, for some $p_0 = 2+\delta$,
\begin{equation}
\begin{aligned}
    \bigg(\fint_{I_r(P)} |R_{I_r}|^{p_0} \bigg)^{1/p_0} & \lesssim \bigg(\fint_{I_{2r}(P)} |R_{I_{r}}|^{2} \bigg)^{1/2} \\
    &\lesssim \bigg(\fint_{I_{2r}(P)} |F|^{2} \bigg)^{1/2} + \bigg(\fint_{I_{2r}(P)} |F_{I_{r}}|^{2} \bigg)^{1/2} \\
    & \lesssim \bigg(\fint_{I_{2r}(P)} |F|^{2} \bigg)^{1/2} + \bigg(\fint_{I_{5r}(P)} |\nabla_{\tan} f|^{2} \bigg)^{1/2}.
    \end{aligned}
\end{equation}
As a consequence of Theorem \ref{thm.real-variable>t}, we have
\begin{equation}
\begin{aligned}
    & \bigg( \fint_{I_R} | M_{100\varepsilon}^{\partial} (\widehat{N}_\varepsilon (\nabla u_\varepsilon))|^{p} d\sigma \bigg)^{1/{p}}  \\
    & \lesssim \bigg( \fint_{I_{2R}} |M_{100\varepsilon}^{\partial}(\widehat{N}_\varepsilon(\nabla u_\varepsilon))|^{2} d\sigma \bigg)^{1/{2}} + \bigg( \fint_{I_{3R}} |M_{100\varepsilon}^{\partial}(\nabla_{\tan} f)|^{p} d\sigma \bigg)^{1/p} \\
     & \lesssim \bigg( \fint_{I_{3R}} |\widehat{N}_\varepsilon(\nabla u_\varepsilon)|^{2} d\sigma \bigg)^{1/{2}} + \bigg( \fint_{I_{4R}} |\nabla_{\tan} f|^{p} d\sigma \bigg)^{1/p}\\
     & \lesssim \bigg( \fint_{I_{3R}} |\widetilde{N}_\varepsilon(\nabla u_\varepsilon)|^{2} d\sigma \bigg)^{1/{2}} + \bigg( \fint_{I_{4R}\cap \Omega_{10\varepsilon}} |\nabla u_\varepsilon|^{2} d\sigma \bigg)^{1/{2}} + \bigg( \fint_{I_{4R}} |\nabla_{\tan} f|^{p} d\sigma \bigg)^{1/p},
    \end{aligned}
\end{equation}
for any $p\in (2,p_0)$, where we have used  Proposition \ref{prop.A1} to remove the boundary average operators $M_{100\varepsilon}^\partial$ in the second inequality and \eqref{est.Mstar-Layer} in the last inequality. Now, to remove $M_{100\varepsilon}^\partial$ on the left-hand side, we use the fact
$0\le \widetilde{N}(\nabla u_\varepsilon) \le \widehat{N}_\varepsilon(\nabla u_\varepsilon)$ and \eqref{est.claim-1}, due to the definition of the large-scale nontangential maximal function. This yields \eqref{est.RpInTR} for $2<p<2+\delta$.

Finally, taking $R = r_0$ and applying a localization argument as in Subsection \ref{subsec.localization}, we obtain
 \begin{equation}
 \begin{aligned}
    &\| \widetilde{N}_\varepsilon(\nabla u_\varepsilon) \|_{L^p(\partial \Omega)} \\
    & \lesssim \| \widetilde{N}_\varepsilon^R(\nabla u_\varepsilon) \|_{L^p(\partial \Omega)} + \| \nabla u \|_{L^2(\Omega\setminus \Omega_{R/2})} \\
    & \lesssim \| \widetilde{N}_\varepsilon(\nabla u_\varepsilon) \|_{L^2(\partial \Omega)} + \bigg( \frac{1}{\varepsilon} \int_{\Omega_{10\varepsilon}} |\nabla u_\varepsilon|^2 \bigg)^{1/2} + \| \nabla_{\tan} f \|_{L^p(\partial \Omega)} + \| \nabla u \|_{L^2(\Omega\setminus \Omega_{R/2})} \\
    & \lesssim \| \nabla_{\tan} f \|_{L^2(\partial \Omega)} + \| \nabla_{\tan} f \|_{L^p(\partial \Omega)} \\
    & \lesssim \| \nabla_{\tan} f \|_{L^p(\partial \Omega)},
 \end{aligned}
 \end{equation}
 where we have used the $(R)_2$ estimate (proved earlier),  the global $L^2$ Rellich estimate \eqref{eq.LSRellich-D} and energy estimate in the third inequality, and the H\"{o}lder inequality in the last inequality. This completes the proof of \eqref{est.Rp} for $2<p<2+\delta$.

