The proof is similar to the regularity problem. It suffices to prove a local estimate in a graph domain $T_{4R}$ for some $R\ge 1000\varepsilon$. Let $u_\varepsilon$ be a solution in $T_{4R}$ with $\frac{\partial u_\varepsilon}{\partial \nu_\varepsilon} = g$ on $I_{4R}$. We would like to show that there exists $\delta>0$ such that for any $p\in (2,2+\delta)$,
\begin{equation}
\begin{aligned}
     & \bigg( \fint_{I_R} | \widetilde{N}_\varepsilon (\nabla u_\varepsilon)|^{p} d\sigma \bigg)^{1/{p}} \\
     & \lesssim \bigg( \fint_{I_{3R}} |\widetilde{N}_\varepsilon(\nabla u_\varepsilon)|^{2} d\sigma \bigg)^{1/{2}} + \bigg( \fint_{I_{4R}\cap \Omega_{10\varepsilon}} |\nabla u_\varepsilon|^{2} d\sigma \bigg)^{1/{2}} + \bigg( \fint_{I_{4R}} |g|^{p} d\sigma \bigg)^{1/p}. 
\end{aligned}
\end{equation}

Again, this is proved by the real-variable argument.
Let $ I_r(P) \subset I_R$ with $4r < R$ and $r>100\varepsilon$. Let 
$$\lambda = |\partial T_{4R} \setminus I_{4r}(P)|^{-1} \int_{I_{4r}(P)} g d\sigma. $$ 
Then we define $g_1 = g \mathbbm{1}_{I_{4r}(P)} + \lambda \mathbbm{1}_{\partial T_{4R} \setminus I_{4r}(P)}$. Then we have $\int_{\partial T_{4R}} g_1 = 0$. Let $u_\varepsilon^1$ be the solution of $\mathcal{L}_\varepsilon(u_\varepsilon^1) = 0$ in $T_{4R}$ and $ \frac{\partial u_\varepsilon^1}{\partial \nu_\varepsilon} = g_1$ on $\partial T_{4R}$. Decompose $u_\varepsilon = u_\varepsilon^1 + u_\varepsilon^2$ and note that $\frac{\partial u_\varepsilon^2}{\partial \nu_\varepsilon} = 0$ on $I_{4r}(P)$.

Let $F = \widehat{N}_\varepsilon(\nabla u_\varepsilon), F_{I_r} = \widehat{N}_\varepsilon(\nabla u^1_\varepsilon)$ and $R_{I_r} =\widehat{N}_\varepsilon(\nabla u_\varepsilon^2)$. By the $(N)_2$ estimate in the Lipschitz domain $T_{4R}$ and the large-scale $L^2$ Rellich estimate \eqref{eq.LSRellich-N}, we have
\begin{equation}
\begin{aligned}
    \fint_{I_{2r}(P)} |F_{I_{r}}|^2 & \lesssim \frac{1}{|I_{2r}(P)|} \int_{I_{2r}(P)} |\widehat{N}_\varepsilon(\nabla u^1_\varepsilon)|^2 \\
    & \lesssim \frac{1}{|I_{2r}(P)|}\int_{I_{4R}} |g_1|^2 
    \lesssim \fint_{I_{4r}(P)} |g|^2.
\end{aligned}
\end{equation}


For $R_{I_r}$, Lemma \ref{lem.RH} yields, for some $p_0 = 2+\delta$,
\begin{equation}
\begin{aligned}
    \bigg(\fint_{I_r(P)} |R_{I_r}|^{p_0} \bigg)^{1/p_0} & \lesssim \bigg(\fint_{I_{2r}(P)} |R_{I_{r}}|^{2} \bigg)^{1/2} \\
    &\lesssim \bigg(\fint_{I_{2r}(P)} |F|^{2} \bigg)^{1/2} + \bigg(\fint_{I_{2r}(P)} |F_{I_{r}}|^{2} \bigg)^{1/2} \\
    & \lesssim \bigg(\fint_{I_{2r}(P)} |F|^{2} \bigg)^{1/2} + \bigg(\fint_{I_{4r}(P)} |g|^{2} \bigg)^{1/2}.
