Now, we estimate $\nabla^2 u_0(X)$ for $X\in T_{1}^{4\varepsilon}$. 




In fact, if $X \in  T_{1}^{4\varepsilon}$ for some $\mathrm{proj}(X) = Q\in I_1$, we have, by the interior estimate for the $\widehat{A}$-harmonic function $u_0$,




\begin{equation}
    |\nabla^2 u_0(X)| \lesssim \delta(X)^{-1} \bigg( \fint_{B(X,\delta(X)/2)} |\nabla u_0|^2 \bigg)^{1/2} \lesssim \delta(X)^{-1} \widehat{N}_\varepsilon(\nabla u_0)(Q).
\end{equation}
This implies that for any $4\varepsilon < t < 1$
\begin{equation}
    \int_{ T_1 \cap \{\delta(X) = t\} } |\nabla^2 u_0(X)|^p d\sigma(X) \lesssim t^{-p} \int_{I_1} |\widehat{N}_\varepsilon(\nabla u_0)(Q)|^p d\sigma(Q).
\end{equation}
By the co-area formula, we have
\begin{equation}\label{est.D2u0.coarea}
\begin{aligned}
    \int_{T_1^{4\varepsilon}} |\nabla^2 u_0(X)|^p dX 
    & \lesssim \int_{4\varepsilon}^{1} dt \int_{T_1 \cap \{ \delta(X) = t\} } |\nabla^2 u_0(X)|^p d\sigma(X) \\
    & \lesssim \int_{4\varepsilon}^{1} t^{-p} dt \int_{I_1 } |\widehat{N}_\varepsilon(\nabla u_0)(Q)|^p d\sigma(Q) \\

    & \lesssim \varepsilon^{1-p} \bigg\{ \int_{I_2} |M_\varepsilon^\partial(\nabla_{\tan} f)|^p d\sigma + \bigg( \int_{\partial T_{2} \setminus I_{2} } |\nabla_{\tan} f|^2 d\sigma \bigg)^{p/2} \bigg\},
\end{aligned}
\end{equation}
where we have used Corollary \ref{coro.L0.hatN} in the last inequality.
Combining this with \eqref{est.Du0-KeDu0}, we obtain
\begin{equation}\label{est.Du0-KDu0.final}
    \| (\nabla u_0 - K_\varepsilon(\nabla u_0)) \eta_\varepsilon \|_{L^p(T_{4/5})}  \lesssim \varepsilon^{1/p} \big( \| M_\varepsilon^\partial(\nabla_{\tan} f) \|_{L^p(I_2)} + \| \nabla_{\tan} f \|_{L^2(\partial T_2 \setminus I_2)} \big).
\end{equation}

Next, we estimate $M_\varepsilon(\nabla u_0(1-\eta_\varepsilon))$. Note that $1-\eta_\varepsilon$ is supported in 
