\label{thm.C1Rellich.Rp}
Let $\Omega$ be a bounded $C^1$ domain.
Let $u_\varepsilon$ be a solution of \eqref{Rp} with $f\in W^{1,2}(\partial \Omega)$. Then for any $2<p<\infty$ and
 any $\varepsilon \le t < {\rm diam}(\Omega)$,
    \begin{equation}\label{est.GlobalLpRellich.C1}
        \bigg( \frac{1}{t} \int_{\Omega_t} |M_\varepsilon(\nabla u_\varepsilon)|^p \bigg)^{1/p} \lesssim \| M_\varepsilon^\partial(\nabla_{\tan} f) \|_{L^p(\partial \Omega)}.
    \end{equation}

The local $L^p$ Rellich estimates in Theorem \ref{thm.LocalRellich.Rp} over a $C^1$ graph domain can be turned into a version for a bounded  $C^1$ domain $\Omega$, namely, for any $P\in \partial \Omega$ and $\varepsilon \le r \le r_0$ (where $r_0$ is a constant depending only on $\Omega$) such that for any $\varepsilon \le t \le r$,
\begin{equation}\label{est.patch-global}
\begin{aligned}
    & \bigg( \frac{1}{t} \int_{\Omega_t \cap D_{r/2}(P)} |M_\varepsilon(\nabla u_\varepsilon)|^p \bigg)^{1/p} \\
    & \qquad \lesssim \bigg( \int_{\Delta_{2r}(P)} |M_\varepsilon^\partial (\nabla_{\tan} f)|^p \bigg)^{1/p} + r^{\frac{d-1}{p} - \frac{d}{2}} \bigg( \int_{D_{2r}(P)} |\nabla u_\varepsilon|^2 \bigg)^{1/2}.
\end{aligned}
\end{equation}
Fix $r = r_0$ and let $\{ P_i: i = 1,2,\cdots, N = N(\Omega) \}$ be a sequence of points on $\partial \Omega$ such that
\begin{equation}
    \Omega_t = \bigcup_{i=1}^{N} ( \Omega_t \cap D_{r_0/2}(P_i) ),
\end{equation}
and $\{ D_{2r_0}(P_i) \}$ have finite overlaps. Hence, applying \eqref{est.patch-global} to each $D_{2r_0}(P_i)$ and summing over $i$, we obtain
\begin{equation}
    \bigg( \frac{1}{t} \int_{\Omega_t} |M_\varepsilon(\nabla u_\varepsilon)|^p \bigg)^{1/p} \lesssim \| M_\varepsilon^\partial (\nabla_{\tan} f) \|_{L^p(\partial \Omega)} + \| \nabla u_\varepsilon \|_{L^2(\Omega)}.
\end{equation}
Finally, the energy estimate implies $\| \nabla u_\varepsilon \|_{L^2(\Omega)} \lesssim \| M_\varepsilon^\partial (\nabla_{\tan} f) \|_{L^p(\partial \Omega)}$. Hence, the last displayed estimate gives \eqref{est.GlobalLpRellich.C1} for $\varepsilon \le t\le r_0$, while the remaining case for $r_0 < t< \mathrm{diam}(\Omega)$ follows from the case $t = r_0$ and the interior large-scale $W^{1,p}$ estimate.

\label{thm.C1Rellich.Np}
Let $\Omega$ be a bounded $C^1$ domain.
Let $u_\varepsilon$ be a solution of \eqref{Np} with $g\in L^2(\partial \Omega)$. Then for any $2<p<\infty$ and
