\label{thm.C1reverse}
    Let $\Omega$ be a bounded $C^1$ domain. Then for any $p\in (2,\infty)$, we have $\overline{\omega}_\varepsilon^X \in B_p(d\sigma)$ uniformly in $\varepsilon$;  i.e., for any $r>0, P\in \partial \Omega, \Delta_r = \Delta_r(P)$ and $X\in \Omega\setminus B_{10r}(P)$
    \begin{equation}
        \bigg( \fint_{\Delta_r} \overline{\omega}_\varepsilon^X(Q)^p d\sigma(Q) \bigg)^{1/p} \lesssim \fint_{\Delta_{r}} \overline{\omega}_\varepsilon^X(Q) d\sigma(Q).
    \end{equation}

    Similar to the proof of Theorem \ref{thm.B2}, we begin with
    \begin{equation}
        \overline{\omega}^X_\varepsilon(Q) \lesssim M_\varepsilon(\nabla G_\varepsilon(X,\cdot))(Q).
    \end{equation}
    Taking $p$th power of this inequality and integrating $Q$ over $\Delta_r(P)$ for $r\gtrsim \varepsilon$, we get
    \begin{equation}\label{est.HM.C1Lp}
    \begin{aligned}
        \int_{\Delta_r} \overline{\omega}_\varepsilon^X(Q)^p d\sigma(Q) & \lesssim \varepsilon^{-1} \int_{\Omega_{2\varepsilon} \cap B_{1.5r}} |M_\varepsilon(\nabla G_\varepsilon(X,\cdot))(Y)|^p dY \\
        & \lesssim r^{-1} \int_{D_{6r}} |M_\varepsilon(\nabla G_\varepsilon(X,\cdot))(Y)|^p dY \\
        & \lesssim r^{-1}|D_{7r}| \bigg( \fint_{D_{7r}} |M_\varepsilon(\nabla G_\varepsilon(X,\cdot))(Y)|^2 dY \bigg)^{p/2} \\
        & \lesssim |\Delta_r| \bigg( \fint_{D_{8r}} |\nabla G_\varepsilon(X,Y)|^2 dY \bigg)^{p/2} \\
        & \lesssim |\Delta_r| r^{-p} \bigg( \fint_{D_{9r}} |G_\varepsilon(X,Y)|^2 dY \bigg)^{p/2} \\
        & \lesssim |\Delta_r| r^{-p} |G_\varepsilon(X, A_{9r}(P))|^p,
    \end{aligned}
    \end{equation}
    where we have used Theorem \ref{thm.LocalRellich.Rp} (with $f = 0$) in the second inequality, Proposition \ref{prop.W1p.local} (with $F = 0$) in the third, Proposition \ref{prop.A1} in the fourth, Caccioppoli inequality in the fifth, and Proposition \ref{prop.hmBasics} \ref{item.G-L2} in the last inequality.

