\end{equation}
for any $p\in (1,\infty)$. This can be proved in a similar manner as Proposition \ref{prop.LS.HLM}, replacing the volume average $M_\varepsilon$ in $\mathbb{R}^d$ by the surface average $M_\varepsilon^\partial$ on $I_{3r}$.
Thus, from \eqref{est.NeDue.loc-e},
\begin{equation}\label{est.local-Rp-Ir}
\begin{aligned}
    \int_{I_r} |\widetilde{N}_\varepsilon^r(\nabla u_\varepsilon)|^p(Q) d\sigma(Q) \lesssim \int_{I_{3r}} |\widetilde{N}_\varepsilon^{3r} (\mathcal{Q}_\varepsilon(u_\varepsilon)) |^p d\sigma + \int_{I_{3r}} |M_\varepsilon^\partial (V_\varepsilon)|^p d\sigma .
\end{aligned}
\end{equation}
We need to estimate the two terms on the right-hand side.

By the $(D)_p$ estimate in Theorem \ref{thm.Dp} with $p>2$ for $\mathcal{Q}_\varepsilon(u_\varepsilon)$ in $T_{t}$ for $t\in (9r,10r-5\varepsilon)$ and $r \ge 10\varepsilon$, we have
\begin{equation}
    \int_{I_{3r}} |\widetilde{N}_\varepsilon^{3r} (\mathcal{Q}_\varepsilon(u_\varepsilon)) |^p d\sigma \lesssim \int_{\partial T_t} |N_\varepsilon(\mathcal{Q}_\varepsilon(u_\varepsilon))|^p d\sigma \lesssim \int_{\partial T_{t}} |M_{4\varepsilon}(\mathcal{Q}_\varepsilon(u_\varepsilon))|^p d\sigma.
\end{equation}
Now, integrating over $t \in (9r,10r-5\varepsilon)$, we have
\begin{equation}
\begin{aligned}
    & \int_{I_{3r}} |\widetilde{N}_\varepsilon^{3r} (\mathcal{Q}_\varepsilon(u_\varepsilon)) |^p d\sigma \\
    & \qquad \lesssim \int_{I_{10r-5\varepsilon}} |M_{4\varepsilon}(\mathcal{Q}_\varepsilon(u_\varepsilon))|^p d\sigma + \frac{1}{r} \int_{T_{10r-5\varepsilon}} |M_{4\varepsilon}(\mathcal{Q}_\varepsilon(u_\varepsilon))|^p dX.
    \end{aligned}
\end{equation}
Recall that
\begin{equation}
    \mathcal{Q}_\varepsilon(u_\varepsilon)(X) = \frac{1}{\varepsilon} \int_0^\varepsilon \frac{\partial u_\varepsilon}{\partial x_d}(x', x_d + t) dt.
\end{equation}
Thus, by Fubini's Theorem and Proposition \ref{prop.Me=MKe}, we have
\begin{equation}
    \int_{I_{10r-5\varepsilon}} |M_{4\varepsilon}(\mathcal{Q}_\varepsilon(u_\varepsilon))|^p d\sigma \lesssim \frac{1}{\varepsilon} \int_{T_{10r} \cap \Omega_{10\varepsilon}} |M_\varepsilon(\nabla u_\varepsilon)|^p
\end{equation}
and
\begin{equation}
    \frac{1}{r} \int_{T_{10r-5\varepsilon}} |M_{4\varepsilon}(\mathcal{Q}_\varepsilon(u_\varepsilon))|^p dX \lesssim \frac{1}{r} \int_{T_{10r}} |M_\varepsilon(\nabla u_\varepsilon)|^p.
\end{equation}
Hence, we obtain
\begin{equation}\label{est.NQe-1}
    \int_{I_{3r}} |\widetilde{N}_\varepsilon^{3r} (\mathcal{Q}_\varepsilon(u_\varepsilon)) |^p d\sigma \lesssim \frac{1}{\varepsilon} \int_{T_{10r} \cap \Omega_{10\varepsilon}} |M_\varepsilon(\nabla u_\varepsilon)|^p + \frac{1}{r} \int_{T_{10r}} |M_\varepsilon(\nabla u_\varepsilon)|^p.
\end{equation}

On the other hand, by Proposition \ref{prop.A1}, 
\begin{equation}
    M_\varepsilon^\partial (V_\varepsilon)(Q) \lesssim \fint_{I_\varepsilon(Q) \times (0,11\varepsilon)} M_\varepsilon(\nabla u_\varepsilon)(X) dX
\end{equation}
By Fubini's Theorem,
\begin{equation}\label{est.MeVe-1}
\begin{aligned}
    \int_{I_{3r}} |M_\varepsilon^\partial (V_\varepsilon)|^p d\sigma & \lesssim \int_{I_{3r}} \fint_{I_{\varepsilon}(Q) \times (0,11\varepsilon)} |M_\varepsilon(\nabla u_\varepsilon)(X)|^p dX d\sigma \\
    & \lesssim \frac{1}{\varepsilon} \int_{I_{3r+\varepsilon} \times (0,11\varepsilon)}  |M_\varepsilon(\nabla u_\varepsilon)(X)|^p dX \\
    & \lesssim \frac{1}{\varepsilon} \int_{T_{4r} \cap \Omega_{20\varepsilon}} |M_\varepsilon(\nabla u_\varepsilon)|^p.
\end{aligned}    
\end{equation}
Hence, combining \eqref{est.NQe-1}, \eqref{est.MeVe-1} with \eqref{est.local-Rp-Ir}, we obtain the desired estimate.

