We only consider the regularity problems in Lipschitz or $C^1$ domains. The estimates for Neumann problems are similar. The Dirichlet problem follows by a classical duality that (full-scale) $(R)_p$ directly implies (full-scale) $(D)_{p'}$; see \cite[Theorem 5.4]{KP93}.

We first recall the local (small-scale) regularity estimate in Lipschitz domains. Let $A(X)$ be H\"{o}lder continuous. Let $u$ be a weak solution of 
\begin{equation}
\left\{
\begin{aligned}
    & -\nabla\cdot (A \nabla u) = 0 \quad \text{in } T_{1}, \\
    & u = f \in C^1(I_1) \quad \text{on }  I_1.
\end{aligned}
\right.
\end{equation}
Then by $(R)_p$ estimates for elliptic operators with $C^\alpha$ coefficients and a localization technique (\cite[Theorem 8.1]{KS11-2} for the case $p = 2$), we have, for any $1<p<2+\delta$,
\begin{equation}\label{est.Ca.Rp}
    \int_{I_{1/2}} |\widetilde{N}(\nabla u)|^p \lesssim \int_{I_1} |\nabla_{\tan} f|^p d\sigma + \int_{T_1} |\nabla u|^p.
\end{equation}


Now, let $u_\varepsilon$ be a weak solution of \eqref{Rp} in a bounded Lipschitz domain $\Omega$. We will first consider $(R)_2$ estimate. Let $P\in \partial \Omega$. By a blow-up argument and \eqref{est.Ca.Rp}, we have
\begin{equation}\label{est.SmallScale.local}
    \int_{\Delta_\varepsilon(P)} |\widetilde{N}^\varepsilon(\nabla u_\varepsilon)|^2 d\sigma \lesssim \int_{\Delta_{100\varepsilon}(P)} |\nabla_{\tan} f|^2 d\sigma + \frac{1}{\varepsilon}\int_{D_{100\varepsilon}(P)} |\nabla u_\varepsilon|^2 d\sigma,
\end{equation}
where $\widetilde{N}^\varepsilon(F)(Q)$ is the truncated nontangential maximal function defined on the boundary layer:
\begin{equation}
\widetilde{N}^\varepsilon(F)(Q) = \sup \bigg\{ \bigg(\fint_{B(X, \delta(X)/2) }|F(Y)|^2 dY \bigg)^{1/2}: X\in \Gamma(Q) \cap \Omega_{10\varepsilon} \bigg\}.
\end{equation}
Integrating \eqref{est.SmallScale.local} over $P\in \partial \Omega$, we have
\begin{equation}
    \| \widetilde{N}^\varepsilon(\nabla u_\varepsilon) \|_{L^2(\partial \Omega)} \lesssim \| \nabla_{\tan} f \|_{L^2(\partial \Omega)} + \bigg( \frac{1}{\varepsilon} \int_{\Omega_{100\varepsilon}} |\nabla u_\varepsilon|^2 \bigg)^{1/2}.
\end{equation}
Note that $\widetilde{N}(\nabla u_\varepsilon) \le \widetilde{N}_\varepsilon(\nabla u_\varepsilon) + \widetilde{N}^\varepsilon(\nabla u_\varepsilon)$ and the large-scale estimate for $\widetilde{N}_\varepsilon(\nabla u_\varepsilon)$ has been given in Theorem \ref{thm.Rp}. It follows that
\begin{equation}\label{est.S+L}
\begin{aligned}
    \| \widetilde{N}(\nabla u_\varepsilon) \|_{L^2(\partial \Omega)} & \le \| \widetilde{N}_\varepsilon(\nabla u_\varepsilon) \|_{L^2(\partial \Omega)} + \| \widetilde{N}^\varepsilon(\nabla u_\varepsilon) \|_{L^2(\partial \Omega)} \\
    & \lesssim \| \nabla_{\tan} f \|_{L^2(\partial \Omega)} + \bigg( \frac{1}{\varepsilon} \int_{\Omega_{100\varepsilon}} |\nabla u_\varepsilon|^2 \bigg)^{1/2} \\
    & \lesssim \| \nabla_{\tan} f \|_{L^2(\partial \Omega)},
    \end{aligned}
\end{equation}
where the last inequality follows from the large-scale Rellich estimate \eqref{eq.LSRellich-D}. Hence, we have proved the full-scale $L^2$ regularity estimate.

Next, as before, the full-scale $L^p$ regularity estimate for $1<p<2$ follows from an interpolation between $L^2$ estimate and $L^1$ estimate with boundary data in Hardy space. While the estimate for $2<p<2+\delta$ follows from the self-improving property of the reverse H\"{o}lder inequality. These are generally the consequences of the full-scale $(R)_2$ estimates; see \cite[Theorem 5.2, 5.3]{KP93} (also see \cite[Theorem 6.2, 6.3]{KP93} for Neumann problem).

Finally, in $C^1$ domains, \eqref{est.Ca.Rp} holds for all $2<p<\infty$; see Appendix \ref{A-D}. By blow-up and covering arguments (as well as a small-scale $W^{1,p}$ estimate), we have
\begin{equation}
\begin{aligned}
    \| \widetilde{N}^\varepsilon(\nabla u_\varepsilon) \|_{L^p(\partial \Omega)} & \lesssim \| \nabla_{\tan} f \|_{L^p(\partial \Omega)} + \bigg( \frac{1}{\varepsilon} \int_{\Omega_{100\varepsilon}} |\nabla u_\varepsilon|^p \bigg)^{1/p} \\
    & \lesssim \| \nabla_{\tan} f \|_{L^p(\partial \Omega)} + \bigg( \frac{1}{\varepsilon} \int_{\Omega_{100\varepsilon}} |M_\varepsilon(\nabla u_\varepsilon)|^p \bigg)^{1/p},
    \end{aligned}
\end{equation}
where the last term can be handled by Theorem \ref{thm.C1Rellich.Rp}. As a result, the desired $L^p$ estimate for $2<p<\infty$ follows similarly as \eqref{est.S+L}.

