Let $A = A(Y)$ be a bounded measurable matrix defined on $\mathbb{R}^d$ satisfying \eqref{ellipticity} and \eqref{periodicity}. Due to the peridoicity, we can view $A$ as a function defined on the flat torus (a periodic cell) $\mathbb{T}^d = [0,1)^d$. Let $\mathcal{L}_1 = -\nabla\cdot (A \nabla)$ be an elliptic operator defined in $\mathbb{R}^d$. The correctors $\{ \chi_j: j=1,2,\cdots, d\}$ are 1-periodic functions satisfying
\begin{equation}
    \left\{
    \begin{aligned}
        & \mathcal{L}_1 (\chi_j) = -\mathcal{L}_1(e_j\cdot Y), \quad \text{for } Y \in \mathbb{R}^d, \\
        & \int_{\mathbb{T}^d} \chi_j = 0.
    \end{aligned}
    \right.
\end{equation}
The homogenized (constant) coefficients $\widehat{A} = (\widehat{a}_{ij})$ are defined by
\begin{equation}\label{eq.hatA}
    \widehat{a}_{ij} = \fint_{\mathbb{T}^d} \Big(a_{ij}(Y) + a_{ik}(Y) \frac{\partial}{\partial y_k} \chi_j(Y) \Big) dY,
\end{equation}
where the repeated index $k$ is summed from $1$ to $d$. The homogenized matrix $\widehat{A}$ also satisfies the ellitpicity condition with the same constant. The homogenized operator is given by $\mathcal{L}_0 = - \nabla\cdot (\widehat{A} \nabla)$. If $A$ is symmetric, then $\widehat{A}$ is also symmetric.

\label{prop.A1}
    Suppose that $\mathcal{O}$ is an open subset of $\mathbb{R}^d$ such that for any $X \in \mathcal{O}, |B_\varepsilon(X) \cap \mathcal{O}| \gtrsim |B_\varepsilon(X)|$. Then for any locally $L^2$ function $f$, and any $1\le p\le 2$
    \begin{equation}\label{est.f<Mef}
        \| f \|_{L^p(\mathcal{O})} \lesssim \| M_\varepsilon( f) \|_{L^p(\mathcal{O})}
    \end{equation}
    Moreover, for any $q \ge 2$,
    \begin{equation}\label{est.Mef<f}
        \| M_\varepsilon( f) \|_{L^q(\mathcal{O})} \lesssim \| f \|_{L^q(B_\varepsilon(\mathcal{O}))}.
    \end{equation}

We first prove \eqref{est.f<Mef}. By the H\"{o}lder inequality and Fubini's Theorem, for $1\le p\le 2$,
\begin{equation}
\begin{aligned}
    \int_{\mathcal{O}} M_\varepsilon(f)^p dX & \ge \int_{\mathcal{O}} \fint_{B_\varepsilon(X)} |f(Y)|^p dY dX \\
    & \ge |B_\varepsilon|^{-1} \int_{B_\varepsilon(\mathcal{O})} \int_{\mathcal{O}} \mathbbm{1}_{\{|X-Y|<\varepsilon\} } |f(Y)|^p dX dY \\
    & \ge |B_\varepsilon|^{-1} \int_{\mathcal{O}} |\mathcal{O} \cap B_\varepsilon(Y)| |f(Y)|^p dY \\
    & \gtrsim \int_{\mathcal{O}} |f(Y)|^p dY,
\end{aligned}
\end{equation}
where we have used the assumption $|B_\varepsilon(Y) \cap \mathcal{O}| \gtrsim |B_\varepsilon(Y)|$ for $Y\in \mathcal{O}$.

To prove \eqref{est.Mef<f}, we use the H\"{o}lder inequality and Fubini's Theorem again,
\begin{equation}
\begin{aligned}
    \int_{\mathcal{O}} |M_\varepsilon(f)|^q dX & \le \int_{\mathcal{O}} \fint_{B_\varepsilon(X)} |f(Y)|^q dY dX \\
    & \le |B_\varepsilon|^{-1} \int_{B_\varepsilon(\mathcal{O})} \int_{\mathcal{O}} \mathbbm{1}_{\{|X-Y| < \varepsilon \} } |f(Y)|^q dX dY  \\
    & \le \int_{B_\varepsilon(\mathcal{O})} |f(Y)|^q dX dY.
    \end{aligned}
\end{equation}
This ends the proof.

