\label{prop.Mef-Bs}
    Let $\varepsilon > 0$. Then for any $s \lesssim \varepsilon$,
    \begin{equation}\label{est.Mef-Bs-1}
        M_\varepsilon(f)(X) \lesssim \fint_{B_s(X)} M_\varepsilon(f),
    \end{equation}
    and
    \begin{equation}\label{est.Mef-Bs-2}
        M_s(M_\varepsilon(f))(X) \lesssim M_{\varepsilon+s}(f)(X) \lesssim M_{2s}(M_\varepsilon(f))(X).
    \end{equation}

Let $X = 0$. Without loss of generality, assume $s < \varepsilon/10$. For any $\theta \in (0,1/2)$, there exists a cone $\mathcal{C}_\theta = \{ X \in \mathbb{R}^d: 1-\theta < \frac{X}{|X|}\cdot v \le 1 \} $ for some $v \in \mathbb{S}^{d-1}$ such that
\begin{equation}\label{est.Mef0}
    M_\varepsilon(f)(0) = \bigg( \fint_{B_\varepsilon(0)} |f(Y)|^2 dY \bigg)^{1/2} \simeq \bigg( |B_\varepsilon|^{-1}\int_{B_\varepsilon(0) \cap \mathcal{C}_\theta} |f(Y)|^2 dY \bigg)^{1/2}.
\end{equation}
Now, observe that if $\theta$ is small enough and $s<\varepsilon/10$, then for any $X \in B_s(0) \cap \mathcal{C}_\theta$, $B_\varepsilon(0) \cap \mathcal{C}_\theta \subset B_\varepsilon(X)$. This and \eqref{est.Mef0} imply that for each $X \in B_\varepsilon(0) \cap \mathcal{C}_\theta$,
\begin{equation}
\begin{aligned}
    M_\varepsilon(f)(X) & = \bigg( \fint_{B_\varepsilon(X)} |f(Y)|^2 dY \bigg)^{1/2} \\
    & \ge \bigg( |B_\varepsilon|^{-1} \int_{B_\varepsilon(0) \cap \mathcal{C}_\theta} |f(Y)|^2 dY \bigg)^{1/2} \simeq M_\varepsilon(f)(0).
\end{aligned}
\end{equation}
It follows that
\begin{equation}
    M^\varepsilon(f)(0) \lesssim \fint_{B_\varepsilon(0) \cap \mathcal{C}_\theta} M_\varepsilon(f)(X) dX \lesssim \fint_{B_\varepsilon(0) } M_\varepsilon(f)(X) dX.
\end{equation}
This proves \eqref{est.Mef-Bs-1}.

The first inequality in \eqref{est.Mef-Bs-2} follows from the simple fact that for each $Y \in B_s(X)$, $M_\varepsilon(f)(Y) \lesssim M_{\varepsilon+s}(f)(X)$. Taking $L^2$ average of $M_\varepsilon(f)(Y)$ over $B_s(X)$, we get the desired estimate. For the second inequality in \eqref{est.Mef-Bs-2}, we apply Fubini's Theorem as follows (assume $X = 0$ for simplicity),
\begin{equation}
    \begin{aligned}
        M_{2s}(M_\varepsilon(f))(0) & = \frac{1}{|B_{2s}| |B_\varepsilon|} \int_{B_{2s}(0)} \int_{B_\varepsilon(Y)} |f(Z)|^2 dZ dY \\
        & = \frac{1}{|B_{2s}| |B_\varepsilon|} \int_{B_{\varepsilon+2s}(0)} |f(Y)|^2 \int_{B_{2s}(0)} \mathbbm{1}_{\{ |Y-Z|<\varepsilon \} } dZ dY.
    \end{aligned}
\end{equation}
Now, the key observation is that for $Y \in B_{\varepsilon+s}(0)$, we have
\begin{equation}
    \int_{B_{2s}(0)} \mathbbm{1}_{\{ |Y-Z|<\varepsilon \} } dZ= | B_{2s}(0) \cap B_\varepsilon(Y) | \gtrsim |B_s(0)|.
\end{equation}
It follows that
\begin{equation}
    M_{2s}(M_\varepsilon(f))(0) \gtrsim \frac{1}{|B_\varepsilon|} \int_{B_{\varepsilon+s}(0)} |f(Y)|^2 dY \simeq M_{\varepsilon+s}(f)(0),
\end{equation}
as desired.

\label{prop.Me=MKe}
    Let $\mathcal{O}$ be an open subset of $\mathbb{R}^d$. Then given $K \ge 1$, 
    \begin{equation}\label{est.Me=MKe}
        \| M_\varepsilon(f) \|_{L^p(\mathcal{O})} \lesssim \| M_{K\varepsilon}(f) \|_{L^p(\mathcal{O})} \lesssim \| M_{\varepsilon}(f) \|_{L^p(B_{K\varepsilon}(\mathcal{O}))},
    \end{equation}
    where the implicit constant depends on $d$ and $K$.

The first inequality is due to the observation
\begin{equation}
    M_\varepsilon(f)(X) \lesssim M_{K\varepsilon}(f)(X) \quad \text{for any } X\in \mathcal{O}.
\end{equation}
To see the second, we use the following covering property: there exists $Z_1,Z_2,\cdots, Z_m \in B_{K\varepsilon}(0)$ with $m$ depending only on $d$ and $K$ such that
\begin{equation}
    B_{K\varepsilon}(0) = \bigcup_{i=1}^m B_\varepsilon(Z_i).
\end{equation}
This implies that
\begin{equation}
    M_{K\varepsilon}(f)(X) \lesssim \sum_{i=1}^m M_\varepsilon(f)(X+Z_i).
\end{equation}
Taking $L^p$ norm on both sides in $X$ over $\mathcal{O}$, we obtain the second inequality in \eqref{est.Me=MKe}.

\label{prop.LS.HLM}
    Let $f \in L^p(\mathbb{R}^d)$ for some $1<p\le \infty$. Then
    \begin{equation}\label{est.Me.Lpbound}
        \| \mathcal{M}^\varepsilon(f) \|_{L^p(\mathbb{R}^d)} \lesssim \| M_\varepsilon(f) \|_{L^p(\mathbb{R}^d)}.
    \end{equation}

Suppose $r>\varepsilon$. Then for any $X\in B_r$, then $|B_r \cap B_\varepsilon(X)| \simeq |B_\varepsilon(X)|$. By Proposition \ref{prop.A1} with $p = 1$,
\begin{equation}
    \fint_{B_r} |f| \lesssim \fint_{B_r} M_\varepsilon(f).
\end{equation}
Thus, by the definition \eqref{def.HardyLittlewood.Me},  we have $\mathcal{M}^\varepsilon(f)(X) \lesssim \mathcal{M} (M_\varepsilon f)(X)$, where $\mathcal{M}$ is the classical Hardy-Littlewood maximal function. Thus, it follows from the $L^p$ boundedness of $\mathcal{M}$ that \eqref{est.Me.Lpbound} holds for any $1<p\le \infty$.

\label{prop.f-Kef}
    Let $\mathcal{O}$ be an open set and  $f$ be  a $W^{1,p}$ function defined in $B_{\varepsilon}(\mathcal{O})$. Then for $1\le p<\infty$,
    \begin{equation}
        \| K_\varepsilon(f) - f \|_{L^p(\mathcal{O})} \le \varepsilon \| \nabla f \|_{L^p(B_\varepsilon(\mathcal{O}))}.
    \end{equation}

Write, for $X\in \mathcal{O}$,
\begin{equation}
    K_\varepsilon f(X)  - f(X) = \int_{B_\varepsilon(0)} \psi_\varepsilon(Y) \int_0^1 \nabla f(X - sY) \cdot Y ds dY.
\end{equation}
By the Minkowski inequality,
\begin{equation}
\begin{aligned}
    \| K_\varepsilon f(\cdot)  - f(\cdot) \|_{L^p(\mathcal{O})} & \le \varepsilon \int_{B_\varepsilon(0)} \psi_\varepsilon(Y) \int_0^1 \| \nabla f(\cdot - sY) \|_{L^p(\mathcal{O})}  ds dY \\
    & \le \varepsilon \| \nabla f \|_{L^p(B_\varepsilon(\mathcal{O}))}.
\end{aligned}
\end{equation}
The proof is complete.

