Let $\mathcal{O}$ be an open set and  $f$ be a function defined in $B_{\varepsilon}(\mathcal{O})$. Let $g \in L^p(\mathbb{T}^d)$ be a 1-periodic function. Then for any $1 \le p < \infty$,
\begin{equation}
    \| g(X/\varepsilon) K_\varepsilon (f)  \|_{L^p(\mathcal{O})} \lesssim \| g \|_{L^p(\mathbb{T}^d)} \| f \|_{L^p(B_{\varepsilon}(\mathcal{O}))}.
\end{equation}

\label{prop.Me(gKef)}
    Let $\mathcal{O}$ be an open set and  $f$ be a function defined in $B_{2\varepsilon}(\mathcal{O}): = \{ X\in \mathbb{R}^d: \mathrm{dist}(X,\mathcal{O}) < \varepsilon \}$. Let $g \in L^2(\mathbb{T}^d)$ be a 1-periodic function. Then for any $2\le p < \infty$,
    \begin{equation}
        \| M_\varepsilon(g(X/\varepsilon) K_\varepsilon (f) ) \|_{L^p(\mathcal{O})} \lesssim \| g \|_{L^2(\mathbb{T}^d)} \| f \|_{L^p(B_{2\varepsilon}(\mathcal{O}))}.
    \end{equation}

Define $T_\varepsilon f = M_\varepsilon(g(X/\varepsilon) K_\varepsilon (f) )$. Clearly, $T_\varepsilon$ is a sublinear operator. We prove the theorem by considering $p = 2$ and $p = \infty$, and then apply the real interpolation theorem.
For $p  = 2$, we have
\begin{equation}
    \| T_\varepsilon f \|_{L^p(\mathcal{O})} \lesssim \| g(X/\varepsilon) K_\varepsilon (f) \|_{L^2(B_\varepsilon(\mathcal{O}))} \lesssim \| g \|_{L^2(\mathbb{T}^d)} \| f \|_{L^2(B_{2\varepsilon}(\mathcal{O}))}.
\end{equation}
For $p = \infty$, 
\begin{equation}
    \| T_\varepsilon f \|_{L^\infty(\mathcal{O})} \lesssim \| f \|_{L^\infty(B_{2\varepsilon}(\mathcal{O}))} \| M_\varepsilon(g(X/\varepsilon)) \|_{L^\infty(B_{\varepsilon}(\mathcal{O}))} \lesssim \| g \|_{L^2(\mathbb{T}^d)} \| f \|_{L^\infty(B_{2\varepsilon}(\mathcal{O}))}.
\end{equation}
The desired estimate follows from Marcinkiewicz interpolation Theorem.

