\label{thm.full real-variable}
Let $B_0$ be a ball in $\mathbb{R}^d$ and $F \in L^2(4B_0)$. Let $q>2$ and $f \in L^p(4B_0)$ for some $2 < p < q$. Suppose that for each ball $B \subset 2B_0$ with $|B| \le c_1 |B_0|$, there exist two measurable functions $F_B$ and $R_B$ on $2B$ such that $|F| \le |F_B| + |R_B|$ on $2B$, and
\begin{equation}\label{cond.real-variable}
\left\{
\begin{aligned}
& \bigg( \fint_{2B} |F_B|^2 \bigg)^{1/2} 
\leq N_1 \sup_{4B_0 \supset B' \supset B} \bigg( \fint_{B'} |f|^2  \bigg)^{1/2},\\
& \bigg( \fint_{2B} |R_B|^q \bigg)^{1/q} 
\leq N_2 \bigg\{ 
\bigg( \fint_{\beta B} |F|^2  \bigg)^{1/2} 
+ \sup_{4B_0 \supset B' \supset B} \bigg(  \fint_{B'} |f|^2 \bigg)^{1/2} 
\bigg\},
\end{aligned}
\right.
\end{equation}
where $N_1, N_2 > 0, 0<c_1<1$ and $\beta > 2$. Then $F \in L^p(B_0)$ and
\begin{equation}
    \bigg( \fint_{B_0} |F|^p \bigg)^{1/p} \le C \bigg\{ \bigg( \fint_{4B_0} |F|^2 \bigg)^{1/2} + \bigg( \fint_{4B_0} |f|^p \bigg)^{1/p} \bigg\},
\end{equation}
where $C$ depends only on $d$, $p$, $q$, $N_1$, $N_2, c_1$, and $\beta$.

\begin{equation}\label{cond.real-variable}
\left\{
\begin{aligned}
& \bigg( \fint_{2B} |F_B|^2 \bigg)^{1/2} 
\leq N_1 \sup_{4B_0 \supset B' \supset B} \bigg( \fint_{B'} |f|^2  \bigg)^{1/2},\\
& \bigg( \fint_{2B} |R_B|^q \bigg)^{1/q} 
\leq N_2 \bigg\{ 
\bigg( \fint_{\beta B} |F|^2  \bigg)^{1/2} 
+ \sup_{4B_0 \supset B' \supset B} \bigg(  \fint_{B'} |f|^2 \bigg)^{1/2} 
\bigg\},
\end{aligned}
\right.
\end{equation}

\label{thm.real-variable>t}
    Let $B_0$ be a ball in $\mathbb{R}^d$ and $F \in L^2(4B_0)$. Let $q>2$ and $f \in L^2(4B_0)$ for some $2 < p < q$. Suppose that there exists $t > 0$ such that for each ball $B \subset 2B_0$ with $|B| \le c_1 |B_0|$ and $\mathrm{diam}(B) > 2t$, there exist two measurable functions $F_B$ and $R_B$ on $2B$ such that $|F| \le |F_B| + |R_B|$ on $2B$, and \eqref{cond.real-variable} holds. Then $M_t(F) \in L^p(B_0)$ and
    \begin{equation}\label{est.real-variable-t}
    \bigg( \fint_{B_0} |M_t(F)|^p \bigg)^{1/p} \le C \bigg\{ \bigg( \fint_{4B_0} |F|^2 \bigg)^{1/2} + \bigg( \fint_{4B_0} |M_t(f)|^p \bigg)^{1/p} \bigg\},
    \end{equation}
    where $C$ depends only on $d$, $p$, $q$, $N_1$, $N_2, c_1$, and $\beta$.

    The proof is simple, using Theorem \ref{thm.full real-variable}. Actually, let $\overline{F} = M_t(F)$. Then $\overline{F}$ satisfies $\overline{F} \le M_t(F_B) + M_t(R_B)$ and the assumption \eqref{cond.real-variable} with $F_B, R_B$ and $f$ replaced by $M_t(F_B), M_t(R_B)$ and $M_t(f)$ for any $B$ with arbitrarily small radius, namely
    \begin{equation}\label{cond.real-variable-t}
\left\{
\begin{aligned}
& \bigg( \fint_{2B} |M_t(F_B)|^2 \bigg)^{1/2} 
\lesssim \sup_{4B_0 \supset B' \supset B} \bigg( \fint_{B'} |M_t(f)|^2  \bigg)^{1/2},\\
& \bigg( \fint_{2B} |M_t(R_B)|^q \bigg)^{1/q} 
\lesssim \bigg\{ 
\bigg( \fint_{\beta B} |\overline{F}|^2  \bigg)^{1/2} 
+ \sup_{4B_0 \supset B' \supset B} \bigg(  \fint_{B'} |M_t(f)|^2 \bigg)^{1/2} 
\bigg\}.
\end{aligned}
\right.
\end{equation}
    In fact, if for $B = B_s$ and $s>t$, then \eqref{cond.real-variable} directly implies \eqref{cond.real-variable-t}, due to the comparison of the $L^2$ norm of $F$ and $M_t(F)$ in Proposition \ref{prop.A1}. For $s<t$, thanks to the first inequality in \eqref{est.Mef-Bs-2}, we have
    \begin{equation}
        \bigg( \fint_{B_{2s}} |M_t(F_B)|^2 \bigg)^{1/2} \lesssim \bigg( \fint_{B_{t+2s}} |F_B|^2 \bigg)^{1/2}.
    \end{equation}
    Now $\mathrm{diam}(B_{t+2s}) = 2(t+2s) > 2t$ and we can apply the first condition in \eqref{cond.real-variable} at this scale and the second inequality in \eqref{est.Mef-Bs-2} to get
    \begin{equation}
        \bigg( \fint_{B_{2s}} |M_t(F_B)|^2 \bigg)^{1/2} \lesssim \sup_{4B_0 \supset B' \supset B_s} \bigg( \fint_{B'} |M_t(f)|^2  \bigg)^{1/2}.
    \end{equation}
    This is a large-scale version of the first condition of \eqref{cond.real-variable}.
    Similarly, a large-scale version of the second condition in \eqref{cond.real-variable} is valid for $M_t(R_B)$. Thus, applying Theorem \ref{thm.full real-variable} to $\overline{F} = M_t(F)$, we get \eqref{est.real-variable-t}. Note that we changed $M_t(F)$ back to $F$ on the right-hand side of \eqref{est.real-variable-t} by \eqref{est.Mef<f}.

If $\Omega$ is $C^1$ and $1<p< \infty$, it was proved  in \cite{Fabes1978} by the method of layer potentials that the Dirichlet problem,
\begin{equation}\label{D-1}
\left\{
\aligned 
& \mathcal{L}_0 (u) =0 \ \ \text{ in } \Omega,\\
& u=f \in L^p(\partial\Omega) \   \text{ on } \partial\Omega \text{ and } N(u) \in L^p(\partial\Omega)
\endaligned
\right.
\end{equation}
is solvable, and that  the solution satisfies the estimate, 
\begin{equation}\label{D-2}
\| N(u) \|_{L^p(\partial\Omega)}
\lesssim \| f \|_{L^p(\partial\Omega)}.
\end{equation}

